window.COURSES = [{"id": "CS 129", "slug": "cs-129-applied-machine-learning", "zh": "应用机器学习", "cat": "基础核心", "type": "ext", "one": "面向应用场景快速过一遍 ML 流程、模型与评估。", "card_desc": "面向应用场景快速过一遍 ML 流程、模型与评估。", "tags": ["应用机器学习"], "difficulty": null, "terms": "2027 春", "units": "3–4", "search": "CS 129 Applied Machine Learning 应用机器学习 面向应用场景快速过一遍 ML 流程、模型与评估。 (Previously numbered CS 229A.) You will learn to implement and apply machine learning algorithms. This course emphasizes practical skills, and focuses on giving you skills to make these algorithms work. You will learn about commonly used learning techniques including supervised learning algorithms (logistic regression, linear regression, SVM, neural networks/deep learning), unsupervised learning algorithms (k-means), as well as learn about specific applications such as anomaly detection and building recommender systems. This class is taught in the flipped-classroom format. You will watch videos and complete in-depth programming assignments and online quizzes at home, then come to class for discussion sections. This class will culminate in an open-ended final project, which the teaching team will help you on. Prerequisites: Programming at the level of CS106B or 106X, and basic linear algebra such as Math 51."}, {"id": "CS 221", "slug": "cs221-artificial-intelligence", "zh": "人工智能：原理与技术", "cat": "基础核心", "type": "core", "one": "AI 的“总览课”：把搜索、MDP、概率图模型、逻辑和机器学习放进同一个“有限信息 + 有限算力下做决策”的框架里。", "card_desc": "AI 的“总览课”：把搜索、MDP、概率图模型、逻辑和机器学习放进同一个“有限信息 + 有限算力下做决策”的框架里。", "tags": ["AI", "基础", "搜索", "概率"], "difficulty": 4, "terms": "2026 秋 / 2027 春", "units": "3–4", "search": "CS 221 人工智能：原理与技术 Artificial Intelligence: Principles and Techniques AI 的“总览课”：把搜索、MDP、概率图模型、逻辑和机器学习放进同一个“有限信息 + 有限算力下做决策”的框架里。 AI 基础 搜索 概率 Overview Learning I Learning II Learning III Search I Search II RL I RL II RL III RL IV Games I Games II Bayesian Networks I Bayesian Networks II Bayesian Networks III Logic I Logic II AI & Society Fireside Chat, Conclusion search MDP game playing Bayesian network logic constraint satisfaction"}, {"id": "CS 224N", "slug": "cs224n-nlp-with-deep-learning", "zh": "自然语言处理与深度学习", "cat": "基础核心", "type": "core", "one": "NLP 从 word2vec 到 LLM 的核心课：作业实现 word2vec、RNN、注意力，最后做一个 LLM 项目。", "card_desc": "NLP 从 word2vec 到 LLM 的核心课：作业实现 word2vec、RNN、注意力，最后做一个 LLM 项目。", "tags": ["NLP", "LLM", "DL", "基础"], "difficulty": 4, "terms": "2027 冬", "units": "3–4", "search": "CS 224N 自然语言处理与深度学习 Natural Language Processing with Deep Learning (LINGUIST 284, SYMSYS 195N) NLP 从 word2vec 到 LLM 的核心课：作业实现 word2vec、RNN、注意力，最后做一个 LLM 项目。 NLP LLM DL 基础 Intro and Word Vectors Word Vectors and Language Models Backpropagation, Neural Networks Dependency Parsing Recurrent Neural Networks Sequence to Sequence Models Attention, Final Projects and LLM Intro Self-Attention and Transformers Pretraining Post-training Benchmarking Efficient Training Reasoning and Agents After DPO NLP, Linguistics, Philosophy word2vec attention transformer BERT GPT QA NLP"}, {"id": "CS 224R", "slug": "cs-224r-deep-reinforcement-learning", "zh": "深度强化学习", "cat": "基础核心", "type": "ext", "one": "从模仿学习到 RLHF，偏深度与机器人/LLM 应用的强化学习。", "card_desc": "从模仿学习到 RLHF，偏深度与机器人/LLM 应用的强化学习。", "tags": ["深度强化学习"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CS 224R Deep Reinforcement Learning 深度强化学习 从模仿学习到 RLHF，偏深度与机器人/LLM 应用的强化学习。 Humans, animals, and robots faced with the world must make decisions and take actions in the world. Moreover, the decisions they choose affect the world they exist in - and those outcomes must be taken into account. This course is about algorithms for deep reinforcement learning - methods for learning behavior from experience, with a focus on practical algorithms that use deep neural networks to learn behavior from high-dimensional observations. Topics will include methods for learning from demonstrations, both model-based and model-free deep RL methods, methods for learning from offline datasets, and more advanced techniques for learning multiple tasks such as goal-conditioned RL, meta-RL, and unsupervised skill discovery. These methods will be instantiated with examples from domains with high-dimensional state and action spaces, such as robotics, visual navigation, and control. This course is complementary to CS234, which neither being a pre-requisite for the other. In comparison to CS234, this course will have a more applied and deep learning focus and an emphasis on use-cases in robotics and motor control. Course Intro + Start of MDPs & Imitation Imitation Learning Policy Gradients Actor-Critic Methods Off-Policy Actor-Critic Methods Q-learning Offline RL Reward Learning RL for LLMs: Preference Optimization (Archit Sharma) RL for LLMs: Reasoning (Noam Brown) Model-Based RL Multi-Task and Goal-Conditioned RL Meta-RL Hierarchical RL and IL RL for Robots: Sim-to-Real Transfer (Guanya Shi) RL for Robots: RL for VLAs Frontiers imitation learning PPO SAC DQN offline RL RLHF meta-RL VLA"}, {"id": "CS 224U", "slug": "cs-224u-natural-language-understanding-linguist-188-linguist-288-symsys-195u", "zh": "自然语言理解", "cat": "基础核心", "type": "ext", "one": "语义表示、推理与评测，比 CS 224N 更偏“理解”和实验。", "card_desc": "语义表示、推理与评测，比 CS 224N 更偏“理解”和实验。", "tags": ["自然语言理解"], "difficulty": null, "terms": "2026–27 未排课", "units": "3–4", "search": "CS 224U Natural Language Understanding (LINGUIST 188, LINGUIST 288, SYMSYS 195U) 自然语言理解 语义表示、推理与评测，比 CS 224N 更偏“理解”和实验。 Project-oriented class focused on developing systems and algorithms for robust machine understanding of human language. Draws on theoretical concepts from linguistics, natural language processing, and machine learning. Topics include lexical semantics, distributed representations of meaning, relation extraction, semantic parsing, sentiment analysis, and dialogue agents, with special lectures on developing projects, presenting research results, and making connections with industry. Prerequisites: CS 224N or CS 224S (This is a smaller number of courses than previously.)"}, {"id": "CS 224W", "slug": "cs224w-machine-learning-with-graphs", "zh": "图机器学习", "cat": "基础核心", "type": "core", "one": "图机器学习：GNN、知识图谱、影响力最大化，把关系数据变成可学习的表示。", "card_desc": "图机器学习：GNN、知识图谱、影响力最大化，把关系数据变成可学习的表示。", "tags": ["图", "GNN", "表示学习"], "difficulty": 3, "terms": "2026 秋", "units": "3–4", "search": "CS 224W 图机器学习 Machine Learning with Graphs 图机器学习：GNN、知识图谱、影响力最大化，把关系数据变成可学习的表示。 图 GNN 表示学习 Introduction Node embeddings Graph neural networks A general perspective on GNNs GNN augmentation and training Theory of GNNs Designing powerful graph encoders Graph Transformers Heterogeneous graphs Knowledge graphs GNNs for recommender systems Relational Deep Learning Advanced architectures in RDL Advanced topics in GNNs Towards Foundation Models for Knowledge Graphs Frontiers in Graph AI Frontiers in Graph AI II GNN node2vec knowledge graph recommender graph transformer"}, {"id": "CS 228", "slug": "cs228-probabilistic-graphical-models", "zh": "概率图模型", "cat": "基础核心", "type": "core", "one": "概率图模型的系统课：表示、推断、学习三件套，是理解贝叶斯方法和结构化预测的基础。", "card_desc": "概率图模型的系统课：表示、推断、学习三件套，是理解贝叶斯方法和结构化预测的基础。", "tags": ["概率", "图模型", "贝叶斯"], "difficulty": 4, "terms": "2026–27 未排课", "units": "3–4", "search": "CS 228 概率图模型 Probabilistic Graphical Models: Principles and Techniques 概率图模型的系统课：表示、推断、学习三件套，是理解贝叶斯方法和结构化预测的基础。 概率 图模型 贝叶斯 Introduction, Probability Theory, Bayesian Networks Undirected models Learning Bayes Nets Exact Inference; Message Passing Sampling MAP Inference; Structured prediction Parameter Learning Bayesian Learning; Structure Learning Exponential families; variational inference Advanced topics and conclusions graphical model message passing variational inference sampling"}, {"id": "CS 229", "slug": "cs229-machine-learning", "zh": "机器学习", "cat": "基础核心", "type": "core", "one": "Stanford ML 旗舰课：用概率和统计把监督学习、无监督学习和学习理论串成一套完整框架。", "card_desc": "Stanford ML 旗舰课：用概率和统计把监督学习、无监督学习和学习理论串成一套完整框架。", "tags": ["ML", "基础", "数学", "统计"], "difficulty": 4, "terms": "2027 冬 / 2027 春", "units": "3–4", "search": "CS 229 机器学习 Machine Learning (STATS 229) Stanford ML 旗舰课：用概率和统计把监督学习、无监督学习和学习理论串成一套完整框架。 ML 基础 数学 统计 Introduction and Basic Concepts Supervised Learning Setup; Linear Regression Weighted Least Squares; Logistic Regression; Newton's Method; GLMs Generative Learning Algorithms Gaussian Discriminant Analysis; Naive Bayes Laplace Smoothing; Support Vector Machines Support Vector Machines; Kernels Bias-Variance Tradeoff; Regularization; Model/Feature Selection Tree Ensembles Neural Networks: Basics Neural Networks: Training Practical Advice for ML Projects K-means; Mixture of Gaussians; Expectation Maximization Factor Analysis Principal Component Analysis; Independent Component Analysis MDPs; Bellman Equations Value Iteration and Policy Iteration; LQR; LQG Q-Learning; Value Function Approximation Policy Search; REINFORCE; POMDPs Optional Topic; Wrap-up bias-variance SVM EM PCA ICA reinforcement learning"}, {"id": "CS 229B", "slug": "cs-229b-machine-learning-for-sequence-modeling-stats-232", "zh": "序列建模", "cat": "基础核心", "type": "ext", "one": "HMM、CRF、RNN 等序列模型及其概率基础。", "card_desc": "HMM、CRF、RNN 等序列模型及其概率基础。", "tags": ["序列建模"], "difficulty": null, "terms": "2026–27 未排课", "units": "3–4", "search": "CS 229B Machine Learning for Sequence Modeling (STATS 232) 序列建模 HMM、CRF、RNN 等序列模型及其概率基础。 Sequence data and time series are becoming increasingly ubiquitous in fields as diverse as bioinformatics, neuroscience, health, environmental monitoring, finance, speech recognition/generation, video processing, and natural language processing. Machine learning has become an indispensable tool for analyzing such data; in fact, sequence models lie at the heart of recent progress in AI like GPT3. This class integrates foundational concepts in time series analysis with modern machine learning methods for sequence modeling. Connections and key differences will be highlighted, as well as how grounding modern neural network approaches with traditional interpretations can enable powerful leaps forward. You will learn theoretical fundamentals, but the focus will be on gaining practical, hands-on experience with modern methods through real-world case studies. You will walk away with a broad and deep perspective of sequence modeling and key ways in which such data are not just 1D images."}, {"id": "CS 229M", "slug": "cs229m-machine-learning-theory", "zh": "机器学习理论", "cat": "基础核心", "type": "core", "one": "机器学习理论：泛化界、非凸优化、隐式正则，回答“为什么深度学习能工作”。", "card_desc": "机器学习理论：泛化界、非凸优化、隐式正则，回答“为什么深度学习能工作”。", "tags": ["理论", "数学", "泛化"], "difficulty": 5, "terms": "2026–27 未排课", "units": "3", "search": "CS 229M 机器学习理论 Machine Learning Theory (STATS 214) 机器学习理论：泛化界、非凸优化、隐式正则，回答“为什么深度学习能工作”。 理论 数学 泛化 learning theory generalization PAC"}, {"id": "CS 230", "slug": "cs230-deep-learning", "zh": "深度学习", "cat": "基础核心", "type": "core", "one": "Ng 的深度学习实战课：从全连接到 CNN/RNN，重点是“把 DL 项目做成功”，而不只是推公式。", "card_desc": "Ng 的深度学习实战课：从全连接到 CNN/RNN，重点是“把 DL 项目做成功”，而不只是推公式。", "tags": ["DL", "实战", "项目"], "difficulty": 3, "terms": "2026 秋", "units": "3–4", "search": "CS 230 深度学习 Deep Learning Ng 的深度学习实战课：从全连接到 CNN/RNN，重点是“把 DL 项目做成功”，而不只是推公式。 DL 实战 项目 Class Introduction and Logistics Deep Learning Intuition Full-Cycle Deep Learning Projects Adversarial Attacks / GANs AI + Healthcare Deep Learning Project Strategy Interpretability of Neural Network Career Advice / Reading Papers Deep Reinforcement Learning Chatbots / Closing Remarks CNN RNN LSTM Adam dropout batch norm healthcare"}, {"id": "CS 231N", "slug": "cs231n-deep-learning-for-computer-vision", "zh": "计算机视觉的深度学习", "cat": "基础核心", "type": "core", "one": "CV 领域最有名的深度学习课：从 kNN 到 Transformer，作业是自己手写反向传播并训练 CNN。", "card_desc": "CV 领域最有名的深度学习课：从 kNN 到 Transformer，作业是自己手写反向传播并训练 CNN。", "tags": ["CV", "DL", "视觉", "项目"], "difficulty": 4, "terms": "2027 春", "units": "3–4", "search": "CS 231N 计算机视觉的深度学习 Deep Learning for Computer Vision CV 领域最有名的深度学习课：从 kNN 到 Transformer，作业是自己手写反向传播并训练 CNN。 CV DL 视觉 项目 Introduction Image Classification with Linear Classifiers Regularization and Optimization Neural Networks and Backpropagation Image Classification with CNNs CNN Architectures Recurrent Neural Networks Attention and Transformers Object Detection, Segmentation, Visualization Video Understanding Large-Scale Distributed Training Self-Supervised Learning Generative Models 1 Generative Models 2 3D Vision Vision and Language Robot Learning Human-Centered AI CNN backprop object detection segmentation GAN self-supervised"}, {"id": "CS 234", "slug": "cs234-reinforcement-learning", "zh": "强化学习", "cat": "基础核心", "type": "core", "one": "强化学习核心课：MDP、值迭代、策略梯度、探索，作业包含 deep RL。", "card_desc": "强化学习核心课：MDP、值迭代、策略梯度、探索，作业包含 deep RL。", "tags": ["RL", "决策", "机器人"], "difficulty": 4, "terms": "2026–27 未排课", "units": "3", "search": "CS 234 强化学习 Reinforcement Learning 强化学习核心课：MDP、值迭代、策略梯度、探索，作业包含 deep RL。 RL 决策 机器人 Introduction Tabular MDP Planning Policy Evaluation Q-Learning and Function Approximation Policy Search 1 Policy Search 2 Policy Search 3 Offline RL 1 Guest Lecture: DPO Offline RL 3 Exploration 1 Exploration 2 Exploration 3 Multi-Agent Game Playing Guest Lecture Value Alignment MDP Q-learning policy gradient PPO DQN exploration"}, {"id": "CS 236", "slug": "cs236-deep-generative-models", "zh": "深度生成模型", "cat": "基础核心", "type": "core", "one": "深度生成模型的理论课：VAE、GAN、flow、diffusion 的概率基础与训练算法。", "card_desc": "深度生成模型的理论课：VAE、GAN、flow、diffusion 的概率基础与训练算法。", "tags": ["生成模型", "Diffusion", "概率"], "difficulty": 4, "terms": "2027 春", "units": "3", "search": "CS 236 深度生成模型 Deep Generative Models 深度生成模型的理论课：VAE、GAN、flow、diffusion 的概率基础与训练算法。 生成模型 Diffusion 概率 Introduction; Probability and Linear Algebra Background + Autoregressive Models Maximum Likelihood Learning + VAEs VAEs + Normalizing Flows Normalizing Flows + GANs GANs + Energy Based Models Energy Based Models + Score Based Models Energy Based Models + Evaluation of Generative Models Score Based Diffusion Models + Discrete Latent Variable Models Diffusion Models for Discrete Data VAE GAN normalizing flow diffusion energy-based model"}, {"id": "CS 246", "slug": "cs-246-mining-massive-data-sets", "zh": "大规模数据挖掘", "cat": "基础核心", "type": "ext", "one": "MapReduce、相似性、推荐、图挖掘与流数据算法。", "card_desc": "MapReduce、相似性、推荐、图挖掘与流数据算法。", "tags": ["大规模数据挖掘"], "difficulty": null, "terms": "2027 冬", "units": "3–4", "search": "CS 246 Mining Massive Data Sets 大规模数据挖掘 MapReduce、相似性、推荐、图挖掘与流数据算法。 The availability of massive datasets is revolutionizing science and industry. This course discusses data mining and machine learning algorithms for analyzing very large amounts of data. Topics include: Big data systems (Hadoop, Spark); Link Analysis (PageRank, spam detection); Similarity search (locality-sensitive hashing, shingling, min-hashing); Stream data processing; Recommender Systems; Analysis of social-network graphs; Association rules; Dimensionality reduction (UV, SVD, and CUR decompositions); Algorithms for large-scale mining (clustering, nearest-neighbor search); Large-scale machine learning (decision tree ensembles); Multi-armed bandit; Computational advertising. Prerequisites: At least one of CS107 or CS145."}, {"id": "CS 312", "slug": "cs-312-deep-learning-alchemy", "zh": "深度学习炼金术", "cat": "基础核心", "type": "ext", "one": "训练技巧、调试与实验方法，讲清楚“为什么有效”。", "card_desc": "训练技巧、调试与实验方法，讲清楚“为什么有效”。", "tags": ["深度学习炼金术"], "difficulty": null, "terms": "2026 秋", "units": "3–5", "search": "CS 312 Deep Learning Alchemy 深度学习炼金术 训练技巧、调试与实验方法，讲清楚“为什么有效”。 Deep learning is now the foundation of all of machine learning and AI, making it more important than ever for students to obtain mastery of the empirical phenomena and experimental skills involved in deep neural networks. How can students acquire the skills necessary to invent the next generation of architectures or develop new broad theories of how deep learning works? This course takes the stance that knowledge or math abilities alone are not enough, and there is no substitute for getting your hands dirty and running many, many experiments. To this end, we will work through computationally tractable domains and take students through the process of obtaining mastery in this domain through efficient experimentation and experiment outcome prediction. More details can be found at https://deep-learning-alchemy.github.io/"}, {"id": "CS 329D", "slug": "cs-329d-machine-learning-under-distributional-shifts", "zh": "分布偏移下的 ML", "cat": "基础核心", "type": "ext", "one": "协变量/标签/概念漂移下的训练、评估与自适应。", "card_desc": "协变量/标签/概念漂移下的训练、评估与自适应。", "tags": ["分布偏移下的 ML"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CS 329D Machine Learning Under Distributional Shifts 分布偏移下的 ML 协变量/标签/概念漂移下的训练、评估与自适应。 The progress of machine learning systems has seemed remarkable and inexorable a wide array of benchmark tasks including image classification, speech recognition, and question answering have seen consistent and substantial accuracy gains year on year. However, these same models are known to fail consistently on atypical examples and domains not contained within the training data. The goal of the course is to introduce the variety of areas in which distributional shifts appear, as well as provide theoretical characterization and learning bounds for distribution shifts. Prerequisites: CS229 or equivalent. Recommended: CS229T (or basic knowledge of learning theory)."}, {"id": "CS 329P", "slug": "cs-329p-practical-machine-learning", "zh": "实用机器学习", "cat": "基础核心", "type": "ext", "one": "数据、特征、模型选择与部署的工程实践。", "card_desc": "数据、特征、模型选择与部署的工程实践。", "tags": ["实用机器学习"], "difficulty": null, "terms": "2026–27 未排课", "units": "3–4", "search": "CS 329P Practical Machine Learning 实用机器学习 数据、特征、模型选择与部署的工程实践。 Applying Machine Learning (ML) to solve real problems accurately and robustly requires more than just training the latest ML model. First, you will learn practical techniques to deal with data. This matters since real data is often not independently and identically distributed. It includes detecting covariate, concept, and label shifts, and modeling dependent random variables such as the ones in time series and graphs. Next, you will learn how to efficiently train ML models, such as tuning hyper-parameters, model combination, and transfer learning. Last, you will learn about fairness and model explainability, and how to efficiently deploy models. This class will teach both statistics, algorithms and code implementations. Homeworks and the final project emphasize solving real problems. Prerequisites: Python programing and machine learning (CS 229), basic statistics. Please view course website here: https://c.d2l.ai/stanford-cs329p/"}, {"id": "CS 330", "slug": "cs-330-deep-multi-task-and-meta-learning", "zh": "多任务与元学习", "cat": "基础核心", "type": "ext", "one": "多任务、few-shot、meta-RL 与迁移学习。", "card_desc": "多任务、few-shot、meta-RL 与迁移学习。", "tags": ["多任务与元学习"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CS 330 Deep Multi-task and Meta Learning 多任务与元学习 多任务、few-shot、meta-RL 与迁移学习。 While deep learning has achieved remarkable success in supervised and reinforcement learning problems, such as image classification, speech recognition, and game playing, these models are, to a large degree, specialized for the single task they are trained for. This course will cover the setting where there are multiple tasks to be solved, and study how the structure arising from multiple tasks can be leveraged to learn more efficiently or effectively. This includes: goal-conditioned reinforcement learning techniques that leverage the structure of the provided goal space to learn many tasks significantly faster; meta-learning methods that aim to learn efficient learning algorithms that can learn new tasks quickly; curriculum and lifelong learning, where the problem requires learning a sequence of tasks, leveraging their shared structure to enable knowledge transfer. This is a graduate-level course. By the end of the course, students should be able to understand and implement the state-of-the-art multi-task learning algorithms and be ready to conduct research on these topics. Prerequisites: CS 229 or equivalent. Familiarity with deep learning, reinforcement learning, and machine learning is assumed."}, {"id": "CS 332", "slug": "cs-332-advanced-survey-of-reinforcement-learning", "zh": "高级强化学习", "cat": "基础核心", "type": "ext", "one": "RL 理论、探索、函数逼近与前沿方向综述。", "card_desc": "RL 理论、探索、函数逼近与前沿方向综述。", "tags": ["高级强化学习"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CS 332 Advanced Survey of Reinforcement Learning 高级强化学习 RL 理论、探索、函数逼近与前沿方向综述。 This class will provide a core overview of essential topics and new research frontiers in reinforcement learning. Planned topics include: model free and model based reinforcement learning, policy search, Monte Carlo Tree Search planning methods, off policy evaluation, exploration, imitation learning, temporal abstraction/hierarchical approaches, safety and risk sensitivity, human-in-the-loop RL, inverse reinforcement learning, learning to communicate, and insights from human learning. Students are expected to create an original research paper on a related topic. Prerequisites: CS 221 or AA 238/CS 238 or CS 234 or CS 229 or similar experience."}, {"id": "CS 120", "slug": "cs-120-introduction-to-ai-safety", "zh": "AI 安全入门", "cat": "LLM 与 Agent", "type": "ext", "one": "从对齐、鲁棒性到滥用风险，建立 AI 安全的基本问题清单。", "card_desc": "从对齐、鲁棒性到滥用风险，建立 AI 安全的基本问题清单。", "tags": ["AI 安全入门"], "difficulty": null, "terms": "2026 秋", "units": "3", "search": "CS 120 Introduction to AI Safety AI 安全入门 从对齐、鲁棒性到滥用风险，建立 AI 安全的基本问题清单。 What makes an AI system &quot;safe&quot; and how do we decide? CS120 explores this question, focusing on both measurement theoretic and institutional challenges of understanding, interpreting, and governing AI capabilities. We distinguish between AI-specific and systemic safety issues, from examining sycophancy and security implications to the challenge of measuring capabilities and risk. This class will look at current solutions and their limitations through CS publications, and will connect the institutions behind AI, how evaluation is defined and audited, and how those factors shape the future risks we might face. Topics will span data work, foundation models, and governance, focusing on threat-models, evaluation, and auditability. This course aims to prepare you to critically assess and contribute to safe AI development, equipping you with knowledge of cutting-edge research and ongoing debates in the field. This course has no official requirements, although we recommend some knowledge about machine learning and statistics, and will include readings, quizzes, and a final project. For more details, see also the course website: https://stanford-cs120.github.io/fall2026/"}, {"id": "CS 221M", "slug": "cs221m-mechanistic-interpretability", "zh": "机制可解释性", "cat": "LLM 与 Agent", "type": "core", "one": "机制可解释性：probing、steering、causal abstraction、sparse autoencoders，理解模型内部到底在算什么。", "card_desc": "机制可解释性：probing、steering、causal abstraction、sparse autoencoders，理解模型内部到底在算什么。", "tags": ["可解释性", "LLM", "Safety", "研究"], "difficulty": 4, "terms": "2027 春", "units": "3", "search": "CS 221M 机制可解释性 Mechanistic Interpretability 机制可解释性：probing、steering、causal abstraction、sparse autoencoders，理解模型内部到底在算什么。 可解释性 LLM Safety 研究"}, {"id": "CS 222", "slug": "cs222-ai-agents-and-simulations", "zh": "AI Agent 与社会模拟", "cat": "LLM 与 Agent", "type": "core", "one": "用 agent-based model 和 generative agents 模拟人类社会，做“what if”实验。", "card_desc": "用 agent-based model 和 generative agents 模拟人类社会，做“what if”实验。", "tags": ["Agent", "社会模拟", "多智能体"], "difficulty": 3, "terms": "2027 冬", "units": "3–4", "search": "CS 222 AI Agent 与社会模拟 AI Agents and Simulations (PSYCH 186) 用 agent-based model 和 generative agents 模拟人类社会，做“what if”实验。 Agent 社会模拟 多智能体"}, {"id": "CS 224C", "slug": "cs-224c-nlp-for-computational-social-science", "zh": "NLP × 计算社会科学", "cat": "LLM 与 Agent", "type": "ext", "one": "用 NLP 方法测量文本中的社会现象与因果关系。", "card_desc": "用 NLP 方法测量文本中的社会现象与因果关系。", "tags": ["NLP × 计算社会科学"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CS 224C NLP for Computational Social Science NLP × 计算社会科学 用 NLP 方法测量文本中的社会现象与因果关系。 We live in an era where many aspects of our social interactions are recorded as textual data, from social media posts to medical and financial records. This course is about using a variety of techniques from machine learning and theories from social science to study human behaviors and important societal questions at scale. Topics will include methods for natural language processing and causal inference, and their applications to important societal questions around hate speech, misinformation, and social movements."}, {"id": "CS 224G", "slug": "cs224g-apps-with-llms-inside", "zh": "LLM 应用开发", "cat": "LLM 与 Agent", "type": "core", "one": "LLM 应用开发课：用 sprint 节奏做 App，理解模型能力边界和新的编程范式。", "card_desc": "LLM 应用开发课：用 sprint 节奏做 App，理解模型能力边界和新的编程范式。", "tags": ["LLM", "产品", "项目"], "difficulty": 3, "terms": "2027 冬", "units": "3–4", "search": "CS 224G LLM 应用开发 Apps With LLMs Inside LLM 应用开发课：用 sprint 节奏做 App，理解模型能力边界和新的编程范式。 LLM 产品 项目"}, {"id": "CS 224S", "slug": "cs-224s-spoken-language-processing-linguist-285", "zh": "语音处理", "cat": "LLM 与 Agent", "type": "ext", "one": "语音识别、合成与理解，传统信号处理加深度模型。", "card_desc": "语音识别、合成与理解，传统信号处理加深度模型。", "tags": ["语音处理"], "difficulty": null, "terms": "2026–27 未排课", "units": "2–4", "search": "CS 224S Spoken Language Processing (LINGUIST 285) 语音处理 语音识别、合成与理解，传统信号处理加深度模型。 Introduction to spoken language technology with an emphasis on dialogue and conversational systems. Deep learning and other methods for automatic speech recognition, speech synthesis, affect detection, dialogue management, and applications to digital assistants and spoken language understanding systems. Prerequisites: CS124, CS221, CS224N, or CS229."}, {"id": "CS 224V", "slug": "cs224v-agentic-ai", "zh": "智能体 AI", "cat": "LLM 与 Agent", "type": "core", "one": "把 LLM 变成能查、能推理、能执行长任务的 agent：RAG、工具、知识库、形式化方法、长程规划。", "card_desc": "把 LLM 变成能查、能推理、能执行长任务的 agent：RAG、工具、知识库、形式化方法、长程规划。", "tags": ["Agent", "RAG", "LLM", "项目"], "difficulty": 4, "terms": "2026 秋", "units": "3–4", "search": "CS 224V 智能体 AI Agentic AI 把 LLM 变成能查、能推理、能执行长任务的 agent：RAG、工具、知识库、形式化方法、长程规划。 Agent RAG LLM 项目 Introduction: LLMs hallucinate — turning them into dependable agents Knowledge Curation: STORM / Co-STORM Research project ideas & AOS architecture Accountable AI: SMT, SatIR, VERDICT Student project ideas Constraint Satisfaction Based Retrievers Constraint Satisfaction Based Retrievers + Project Proposals How to RAG without hallucination: WikiChat Project Proposals ReAct Agents for Querying Knowledge Bases and Graphs Agentic Data-Driven Research: DataSTORM Querying Hybrid (Structured and Unstructured) Data: SUQL Long-Context Long-Horizon Deep Researcher: SLIDERS Minimizing hallucination in task-oriented agents: Genie Worksheet Coding Agents: anatomy of Claude Code / Codex VLMs for Transcription of historical manuscripts Training LLMs: instruction following and training data RAG agent STORM SUQL tool use hallucination"}, {"id": "CS 25", "slug": "cs25-transformers-united", "zh": "Transformers United", "cat": "LLM 与 Agent", "type": "core", "one": "Transformer 宇宙的公开讲座：每周一位顶级研究者讲 LLM、生成、机器人、科学应用。", "card_desc": "Transformer 宇宙的公开讲座：每周一位顶级研究者讲 LLM、生成、机器人、科学应用。", "tags": ["Transformer", "讲座", "前沿"], "difficulty": 1, "terms": "2026–27 未排课", "units": "1", "search": "CS 25 Transformers United Transformers United V6 (SYMSYS 25) Transformer 宇宙的公开讲座：每周一位顶级研究者讲 LLM、生成、机器人、科学应用。 Transformer 讲座 前沿 Overview of Transformers From Representation Learning to World Modeling On the Tradeoffs of State Space Models and Transformers The Ultra-Scale Talk: Scaling Training to Thousands of GPUs From Next-Token Prediction to Next-Generation Intelligence Serving Transformers: Lessons from the Trenches Generalist Agents in Open-Ended Worlds (Jim Fan) Whole-Part Hierarchies in a Neural Network (Geoffrey Hinton) transformer attention LLM"}, {"id": "CS 324", "slug": "cs324-advances-in-foundation-models", "zh": "基础模型进展", "cat": "LLM 与 Agent", "type": "core", "one": "基础模型的全景课：模型/算法、系统/基础设施、伦理/社会影响，加上手把手项目。", "card_desc": "基础模型的全景课：模型/算法、系统/基础设施、伦理/社会影响，加上手把手项目。", "tags": ["Foundation Model", "LLM", "多模态"], "difficulty": 3, "terms": "2026–27 未排课", "units": "3", "search": "CS 324 基础模型进展 Advances in Foundation Models 基础模型的全景课：模型/算法、系统/基础设施、伦理/社会影响，加上手把手项目。 Foundation Model LLM 多模态"}, {"id": "CS 329A", "slug": "cs329a-self-improving-ai-agents", "zh": "自我改进的 AI Agent", "cat": "LLM 与 Agent", "type": "core", "one": "研究型 seminar：自我改进、verifier、test-time compute、搜索、工具、多模态 web、长程规划。", "card_desc": "研究型 seminar：自我改进、verifier、test-time compute、搜索、工具、多模态 web、长程规划。", "tags": ["Agent", "研究", "推理", "Self-improvement"], "difficulty": 4, "terms": "2027 春", "units": "3", "search": "CS 329A 自我改进的 AI Agent Self Improving AI Agents 研究型 seminar：自我改进、verifier、test-time compute、搜索、工具、多模态 web、长程规划。 Agent 研究 推理 Self-improvement Course Overview Test-time Compute Scaling Robust Verification Learning from Feedback with Tools / Code Multi-step Reasoning / Planning Train-Time Scaling / Scaling RL Open-Ended Evolution of Self-Improving Agents Self-Improvement with Search & Deep Research Agents Guest Lecture: Melvin Johnson — Evolution of Post-training Midterm Presentations Midterm Presentations Midterm Presentations Agentic Frameworks for Software Engineering Augmenting Agents with Memory (Junchen Jiang) Guest Lecture: Denny Zhou — LLM Reasoning Guest Lecture: Thang Luong — AlphaProof, AlphaGeometry & Gemini IMO Agentic Evaluations & Long-Horizon Tasks Guest Lecture: Misha Laskin — Building Agentic Systems for Autonomy Guest Lecture: Danny Driess — Multimodal AI Agents in Robotics Future Research Areas test-time compute self-improvement agent deep research"}, {"id": "CS 329H", "slug": "cs329h-machine-learning-from-human-preferences", "zh": "从人类偏好中学习", "cat": "LLM 与 Agent", "type": "core", "one": "RLHF 的理论与实作：从 choice model、偏好学习到 assistance games 和公平性。", "card_desc": "RLHF 的理论与实作：从 choice model、偏好学习到 assistance games 和公平性。", "tags": ["RLHF", "偏好", "对齐", "推荐"], "difficulty": 4, "terms": "2026 秋", "units": "3", "search": "CS 329H 从人类偏好中学习 Machine Learning from Human Preferences RLHF 的理论与实作：从 choice model、偏好学习到 assistance games 和公平性。 RLHF 偏好 对齐 推荐 Course introduction & motivation Choice data, generalization, and Bradley–Terry Random utility models and axiomatizations Factor models Learning to predict choice; latent-variable estimation with MLE Bayesian estimation and finetuning Fisher information & optimal experimental design Reinforcement learning from human feedback Direct preference optimization Active elicitation for LLMs, and case studies Assistance games; assisted vs. contextual bandits Acquisition functions & Thompson sampling Dueling bandits & preferential Bayesian optimization Style control, surrogates Bounded rationality; computationally tractable choice Impossibilities: Gibbard–Satterthwaite and Arrow Fairness and information aggregation Summary and practical tips Bradley-Terry RLHF DPO bandit preference"}, {"id": "CS 329M", "slug": "cs-329m-machine-programming", "zh": "Machine Programming", "cat": "LLM 与 Agent", "type": "ext", "one": "用 ML 做代码生成、程序合成与软件工程自动化。", "card_desc": "用 ML 做代码生成、程序合成与软件工程自动化。", "tags": ["Machine Programming"], "difficulty": null, "terms": "2026 秋", "units": "3–4", "search": "CS 329M Machine Programming Machine Programming 用 ML 做代码生成、程序合成与软件工程自动化。 The field of machine programming (MP) is concerned with the automation of software development. Given the recent advances in software algorithms, hardware efficiency and capacity, and an ever increasing availability of code data, it is now possible to train machines to help develop software. In this course, we teach students how to build real-world MP systems. We begin with a high-level overview of the field, including an abbreviated analysis of state-of-the-art (e.g., Merly Mentor). Next, we discuss the foundations of MP and the key areas for innovation, some of which are unique to MP. We close with a discussion of current limitations and future directions of MP. This course includes a nine-week hands-on project, where students (as individuals or in a small group) will create their own MP system and demonstrate it to the class. This course is primary intended for graduate students (it is not recommended for undergraduate students without first reviewing that the course prerequisites are met)."}, {"id": "CS 329T", "slug": "cs329t-trustworthy-machine-learning", "zh": "可信机器学习：构建与评估 Agent 系统", "cat": "LLM 与 Agent", "type": "core", "one": "可信 agent 系统：先搭 prototype，再用 eval 把它打磨到可靠。", "card_desc": "可信 agent 系统：先搭 prototype，再用 eval 把它打磨到可靠。", "tags": ["Agent", "可信", "Eval", "项目"], "difficulty": 3, "terms": "2026–27 未排课", "units": "3", "search": "CS 329T 可信机器学习：构建与评估 Agent 系统 Trustworthy Machine Learning: Building and evaluating agentic systems 可信 agent 系统：先搭 prototype，再用 eval 把它打磨到可靠。 Agent 可信 Eval 项目"}, {"id": "CS 329X", "slug": "cs-329x-human-centered-nlp-cs-129x", "zh": "人本 NLP", "cat": "LLM 与 Agent", "type": "ext", "one": "以人为中心的 NLP，关注用户、协作与交互式系统。", "card_desc": "以人为中心的 NLP，关注用户、协作与交互式系统。", "tags": ["人本 NLP"], "difficulty": null, "terms": "2026 秋", "units": "3", "search": "CS 329X Human Centered NLP (CS 129X) 人本 NLP 以人为中心的 NLP，关注用户、协作与交互式系统。 Recent advances in natural language processing (NLP), especially around large pretrained models, have enabled extensive successful applications. However, there are growing concerns about the negative aspects of NLP systems, such as biases and a lack of input from users. This course gives an overview of human-centered techniques and applications for NLP, ranging from human-centered design thinking to human-in-the-loop algorithms, fairness, and accessibility. Along the way, we will cover machine-learning techniques which are especially relevant to NLP and to human experiences."}, {"id": "CS 329Z", "slug": "cs329z-engineering-ai-agents", "zh": "AI Agent 工程", "cat": "LLM 与 Agent", "type": "core", "one": "从 LLM pipeline 到 compound AI system 再到 autonomous agent 的工程方法论：选问题、拆解、选组件、做 eval。", "card_desc": "从 LLM pipeline 到 compound AI system 再到 autonomous agent 的工程方法论：选问题、拆解、选组件、做 eval。", "tags": ["Agent", "工程", "RAG", "Eval"], "difficulty": 4, "terms": "2026 秋", "units": "3", "search": "CS 329Z AI Agent 工程 Engineering AI Agents 从 LLM pipeline 到 compound AI system 再到 autonomous agent 的工程方法论：选问题、拆解、选组件、做 eval。 Agent 工程 RAG Eval Foundations & Landscape: What Are Agentic Systems? Retrieval-Augmented Generation (RAG) Tool Use & Function Calling Agent Design Patterns & Scaffolds Frameworks & Orchestration Agent Memory Architectures Multi-Agent Systems Optimization Data for Agents: Selection & Quality Evaluation: Fundamentals & Benchmark Design LLM-as-Judge & Eval Infrastructure Agent Safety & Guardrails agent engineering eval tool use memory"}, {"id": "CS 336", "slug": "cs336-language-modeling-from-scratch", "zh": "从零构建语言模型", "cat": "LLM 与 Agent", "type": "core", "one": "从零造一个语言模型：数据清洗、tokenizer、Transformer、训练、scaling、eval、部署。", "card_desc": "从零造一个语言模型：数据清洗、tokenizer、Transformer、训练、scaling、eval、部署。", "tags": ["LLM", "预训练", "系统", "硬核"], "difficulty": 5, "terms": "2027 春", "units": "3–5", "search": "CS 336 从零构建语言模型 Language Modeling from Scratch 从零造一个语言模型：数据清洗、tokenizer、Transformer、训练、scaling、eval、部署。 LLM 预训练 系统 硬核 Course Introduction & Tokenization PyTorch / Building a Transformer Architecture & Hyperparameters Attention Alternatives & Mixture of Experts GPUs, TPUs Kernels, Triton, XLA Parallelism 1 Parallelism 2 Scaling Laws Inference Scaling Laws 2 Evaluation Data: Sources, Datasets Data: Filtering & Deduplication Mid / Post-Training Post-Training: RLVR Alignment & Multimodal Guest Lecture: Dan Fu tokenizer transformer scaling law GPU training"}, {"id": "CS 338", "slug": "cs-338-aligning-superintelligence-mse-338", "zh": "对齐超级智能", "cat": "LLM 与 Agent", "type": "ext", "one": "超级智能的对齐、治理与安全策略。", "card_desc": "超级智能的对齐、治理与安全策略。", "tags": ["对齐超级智能"], "difficulty": null, "terms": "2027 春", "units": "3", "search": "CS 338 Aligning Superintelligence (MS&E 338) 对齐超级智能 超级智能的对齐、治理与安全策略。 Within a couple of decades, or less, it is plausible that humans will create an AI that is much smarter than humans in practically all domains of human activity. We refer to such an AI as a superintelligence. The alignment problem is how to make sure that such a superintelligence acts according to its creator's intent. This course is intended for a technical audience interested in thinking about this problem. Prerequisites: one graduate-level machine learning course and one course that studies agents (e.g., AI, RL, decision analysis, economics)."}, {"id": "CS 362", "slug": "cs-362-research-in-ai-alignment", "zh": "AI 对齐研究", "cat": "LLM 与 Agent", "type": "ext", "one": "对齐研究的阅读、复现与项目实践。", "card_desc": "对齐研究的阅读、复现与项目实践。", "tags": ["AI 对齐研究"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CS 362 Research in AI Alignment AI 对齐研究 对齐研究的阅读、复现与项目实践。 In this course we will explore the current state of research in the field of AI alignment, which seeks to bring increasingly intelligent AI systems in line with human values and interests. As the energy in the AI alignment landscape has been increasingly focused on political considerations, we seek to create a space to discuss which direction we should be pointing in, now that we have a better idea of what AI scaling will look like in the near future. This is a philosophical task, and we will invite several speakers that are philosophical in persuasion, but we also find that several of the most relevant philosophical questions cannot be asked without a strong technical familiarity with the specifics of language models and reinforcement learning. The format will consist of weekly lectures in which speakers present their relationships to the alignment problem and their current research approaches. Before each speaker, we will have some corresponding assigned readings and we will assign some form of active engagement with the material: we will accept a blog post in response to the ideas in the readings, but we will encourage jupyter notebooks that engage with the technical material directly. Therefore this course requires research experience, preferably using mathematical and programming tools (e.g. Python, PyTorch, calculus), and is a graduate level course, open to advanced undergraduates."}, {"id": "CS 372", "slug": "cs372-agi-reasoning-planning", "zh": "AGI 的推理、规划与决策", "cat": "LLM 与 Agent", "type": "core", "one": "AGI 的推理、规划与决策：从 System 1 到 System 2、多 LLM 协作、时序推理。", "card_desc": "AGI 的推理、规划与决策：从 System 1 到 System 2、多 LLM 协作、时序推理。", "tags": ["AGI", "推理", "规划", "多 Agent"], "difficulty": 4, "terms": "2027 冬", "units": "3", "search": "CS 372 AGI 的推理、规划与决策 Artificial General Intelligence for Reasoning, Planning, and Decision Making AGI 的推理、规划与决策：从 System 1 到 System 2、多 LLM 协作、时序推理。 AGI 推理 规划 多 Agent"}, {"id": "CS 521", "slug": "cs-521-seminar-on-ai-safety", "zh": "AI 安全 seminar", "cat": "LLM 与 Agent", "type": "ext", "one": "AI 安全前沿论文与研究方向讨论。", "card_desc": "AI 安全前沿论文与研究方向讨论。", "tags": ["AI 安全 seminar"], "difficulty": null, "terms": "2026–27 未排课", "units": "1", "search": "CS 521 Seminar on AI Safety AI 安全 seminar AI 安全前沿论文与研究方向讨论。 In this seminar, we will focus on the challenges in the design of safe and verified AI-based systems. We will explore some of the major problems in this area from the viewpoint of industry and academia. We plan to have a weekly seminar speaker to discuss issues such as verification of AI systems, reward misalignment and hacking, secure and attack-resilient AI systems, diagnosis and repair, issues regarding policy and ethics, as well as the implications of AI safety in automotive industry. Prerequisites: There are no official prerequisites but an introductory course in artificial intelligence is recommended."}, {"id": "MS&E 338", "slug": "mse-338-aligning-superintelligence-cs-338", "zh": "对齐超级智能", "cat": "LLM 与 Agent", "type": "ext", "one": "与 CS 338 交叉的对齐与治理。", "card_desc": "与 CS 338 交叉的对齐与治理。", "tags": ["对齐超级智能"], "difficulty": null, "terms": "2027 春", "units": "3", "search": "MS&E 338 Aligning Superintelligence (CS 338) 对齐超级智能 与 CS 338 交叉的对齐与治理。 Within a couple of decades, or less, it is plausible that humans will create an AI that is much smarter than humans in practically all domains of human activity. We refer to such an AI as a superintelligence. The alignment problem is how to make sure that such a superintelligence acts according to its creator's intent. This course is intended for a technical audience interested in thinking about this problem. Prerequisites: one graduate-level machine learning course and one course that studies agents (e.g., AI, RL, decision analysis, economics)."}, {"id": "PSYCH 239", "slug": "psych-239-do-language-models-have-mental-states", "zh": "LLM 有心理状态吗", "cat": "LLM 与 Agent", "type": "ext", "one": "用心理学框架讨论 LLM 的心智归因。", "card_desc": "用心理学框架讨论 LLM 的心智归因。", "tags": ["LLM 有心理状态吗"], "difficulty": null, "terms": "2027 春", "units": "3", "search": "PSYCH 239 Do Language Models Have Mental States LLM 有心理状态吗 用心理学框架讨论 LLM 的心智归因。 Do large language models (LLMs) understand what they say? Do they have desires? Do they feel pain or emotions? How can we know? In this class we will survey philisophical background on the nature of mental states and read recent papers on LLM representations. We will try to gain clarity about the nature of mental states and whether LLMs have them now or might in the future. We may stray into hard problems of consciousness and qualia."}, {"id": "STATS 292", "slug": "stats-292-statistical-models-of-text-and-language", "zh": "文本统计模型", "cat": "LLM 与 Agent", "type": "ext", "one": "文本的统计建模、语言模型与统计推断。", "card_desc": "文本的统计建模、语言模型与统计推断。", "tags": ["文本统计模型"], "difficulty": null, "terms": "2027 春", "units": "3", "search": "STATS 292 Statistical Models of Text and Language 文本统计模型 文本的统计建模、语言模型与统计推断。 This course examines the statistical foundations of text and language, emphasizing explicit probabilistic models rather than black-box NLP techniques. Language follows well-defined statistical laws that govern word frequency, predictability, and variation. Understanding these properties enables quantitative text analysis, measurement of information content, and development of interpretable models used in linguistics, information retrieval, and computational text processing. As large-scale textual data continues to grow, statistical methods are crucial for detecting patterns, analyzing linguistic trends, and constructing efficient, interpretable models. Key topics include: Word Frequency Distributions (Zipf's and Heaps' laws); Entropy &amp; Information Theory (redundancy and uncertainty in language); Probabilistic Language Models (n-grams, smoothing, perplexity); Markov Models &amp; Hidden Markov Chains (stochastic text sequences); Text Similarity &amp; Distance Metrics (measuring divergence in text); Corpus Statistics &amp; Sampling (estimating linguistic trends); Random Processes in Text Generation (stochastic models of language). By the end of the course, students will develop a strong foundation in statistical text analysis, equipping them with essential tools for computational linguistics, AI, search technologies, and digital humanities in an increasingly data-driven world."}, {"id": "CS 217", "slug": "cs217-hardware-accelerators-for-ml", "zh": "机器学习硬件加速器", "cat": "ML 系统与硬件", "type": "core", "one": "ML 硬件加速器：数据流、张量处理、存储层次、编译，以及 CNN/Transformer 的映射。", "card_desc": "ML 硬件加速器：数据流、张量处理、存储层次、编译，以及 CNN/Transformer 的映射。", "tags": ["硬件", "加速器", "体系结构", "芯片"], "difficulty": 4, "terms": "2027 春", "units": "3–4", "search": "CS 217 机器学习硬件加速器 Hardware Accelerators for Machine Learning (EE 244) ML 硬件加速器：数据流、张量处理、存储层次、编译，以及 CNN/Transformer 的映射。 硬件 加速器 体系结构 芯片 Introduction High-Level Synthesis Data Parallelism and Efficiency Metrics Quantization Systolic Arrays Vector and Scalar Units Memory Systems Interconnects and Network-on-Chip Compilers and Software Stack (Part 1) Compilers and Software Stack (Part 2) Review of Project Proposals (I) Review of Project Proposals (II) GPU Architectures Reconfigurable Dataflow Architectures SambaNova RDA (Raghu Prabhakar) Memory-Centric Computing (Part 1) Memory-Centric Computing (Part 2) AWS Inferentia and Trainium (Nafea Bshara) NVIDIA GPU Architecture for AI (Ronny Krashinsky) Poster Sessions accelerator systolic array quantization HLS FPGA"}, {"id": "CS 229S", "slug": "cs229s-systems-for-machine-learning", "zh": "机器学习系统", "cat": "ML 系统与硬件", "type": "core", "one": "ML 系统：数据准备、训练、部署推理全栈的效率优化，软硬件协同。", "card_desc": "ML 系统：数据准备、训练、部署推理全栈的效率优化，软硬件协同。", "tags": ["MLSys", "系统", "分布式", "性能"], "difficulty": 4, "terms": "2026–27 未排课", "units": "3", "search": "CS 229S 机器学习系统 Systems for Machine Learning ML 系统：数据准备、训练、部署推理全栈的效率优化，软硬件协同。 MLSys 系统 分布式 性能"}, {"id": "CS 253", "slug": "cs-253-securing-ai-systems", "zh": "AI 系统安全", "cat": "ML 系统与硬件", "type": "ext", "one": "模型窃取、对抗样本、数据投毒与 LLM 系统攻击面。", "card_desc": "模型窃取、对抗样本、数据投毒与 LLM 系统攻击面。", "tags": ["AI 系统安全"], "difficulty": null, "terms": "2027 春", "units": "3", "search": "CS 253 Securing AI Systems AI 系统安全 模型窃取、对抗样本、数据投毒与 LLM 系统攻击面。 The explosive growth of AI systems has created new cybersecurity challenges. Systems that work well on benign prompts can be subverted with adversarial inputs that are easily disguised. The ensuing set of security problems gave rise to a new area of research, called AI security, that now spans thousands of research papers per year in multiple academic conferences. This course will introduce students to the key challenges of AI security, including modern approaches for securing computer systems that rely on AI models. The course content will evolve from year to year based on the latest research in the area."}, {"id": "CS 329E", "slug": "cs-329e-machine-learning-on-embedded-systems-ee-292d", "zh": "嵌入式 ML", "cat": "ML 系统与硬件", "type": "ext", "one": "在 MCU、手机与边缘设备上部署和压缩模型。", "card_desc": "在 MCU、手机与边缘设备上部署和压缩模型。", "tags": ["嵌入式 ML"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CS 329E Machine Learning on Embedded Systems (EE 292D) 嵌入式 ML 在 MCU、手机与边缘设备上部署和压缩模型。 This is a project-based class where students will learn how to develop machine learning models for execution in resource constrained environments such as embedded systems. In this class students will learn about techniques to optimize machine learning models and deploy them on a device such as a Arduino, Raspberry PI, Jetson, or Edge TPUs. The class has a significant project component."}, {"id": "CS 329S", "slug": "cs329s-machine-learning-systems-design", "zh": "机器学习系统设计", "cat": "ML 系统与硬件", "type": "core", "one": "ML 系统设计：从数据管理到部署监控，以及隐私、公平、安全等“人”的问题。", "card_desc": "ML 系统设计：从数据管理到部署监控，以及隐私、公平、安全等“人”的问题。", "tags": ["MLSys", "工程", "部署", "项目"], "difficulty": 3, "terms": "2026–27 未排课", "units": "3–4", "search": "CS 329S 机器学习系统设计 Machine Learning Systems Design ML 系统设计：从数据管理到部署监控，以及隐私、公平、安全等“人”的问题。 MLSys 工程 部署 项目 Understanding machine learning production ML and Data Systems Fundamentals Training Data Feature engineering Model selection, development, and training Offline evaluation Model evaluation Deployment Deployment tutorials Diagnosis of ML system failures, distribution shifts, monitoring Monitoring & Continual Learning ML Infrastructure and Platform ML system design feature store monitoring deployment"}, {"id": "CS 349D", "slug": "cs349d-ai-inference-infrastructure", "zh": "AI 推理基础设施", "cat": "ML 系统与硬件", "type": "core", "one": "AI 推理基础设施：compound AI systems 在云上如何部署、调度、扩展。", "card_desc": "AI 推理基础设施：compound AI systems 在云上如何部署、调度、扩展。", "tags": ["推理", "基础设施", "云", "系统"], "difficulty": 4, "terms": "2027 春", "units": "3", "search": "CS 349D AI 推理基础设施 AI Inference Infrastructure AI 推理基础设施：compound AI systems 在云上如何部署、调度、扩展。 推理 基础设施 云 系统 Introduction Parallelism Serving Engines Programming Assignment Meeting 1 Batching Disaggregation Speculative Decoding SGLang (Ying Sheng, RadixArk) Context Management Efficient Attention Hybrid LLMs Mixture of Experts Programming Assignment Meeting 2 Load Balancing & Routing Agentic Workflows Memory Reinforcement Learning Multi-tenancy Project Presentations inference serving batching KV cache speculative decoding MoE"}, {"id": "CS 349E", "slug": "cs349e-efficient-ml-inference-at-scale", "zh": "大规模高效 ML 推理", "cat": "ML 系统与硬件", "type": "core", "one": "大规模高效推理：模型优化、分布式 serving、AI 硬件、kernel、编译器。", "card_desc": "大规模高效推理：模型优化、分布式 serving、AI 硬件、kernel、编译器。", "tags": ["推理", "性能", "硬件", "编译"], "difficulty": 5, "terms": "2026 秋", "units": "3", "search": "CS 349E 大规模高效 ML 推理 Efficient ML Inference at Scale (EE 339) 大规模高效推理：模型优化、分布式 serving、AI 硬件、kernel、编译器。 推理 性能 硬件 编译 Introduction / Rooflines Model Optimization & Quantization Distributed Serving Disaggregated Serving AI Hardware & Performance Modeling Kernel Development Kernel Optimization Techniques ML Compilers: Frontends ML Compilers: Backends Agentic Kernel Generation efficient inference quantization pruning distillation"}, {"id": "CS 349F", "slug": "cs349f-fabric-architectures-for-ai-systems", "zh": "AI 系统的网络 Fabric 架构", "cat": "ML 系统与硬件", "type": "core", "one": "AI 集群的网络 fabric：fat tree、拥塞控制、调度，追求超低延迟和近 100% goodput。", "card_desc": "AI 集群的网络 fabric：fat tree、拥塞控制、调度，追求超低延迟和近 100% goodput。", "tags": ["网络", "集群", "数据中心", "系统"], "difficulty": 4, "terms": "2026 秋", "units": "2", "search": "CS 349F AI 系统的网络 Fabric 架构 Fabric Architectures For AI Systems AI 集群的网络 fabric：fat tree、拥塞控制、调度，追求超低延迟和近 100% goodput。 网络 集群 数据中心 系统"}, {"id": "CS 349H", "slug": "cs-349h-software-techniques-for-emerging-hardware-platforms-ee-349", "zh": "新硬件软件技术", "cat": "ML 系统与硬件", "type": "ext", "one": "为 FPGA、加速器等新型硬件写高效软件。", "card_desc": "为 FPGA、加速器等新型硬件写高效软件。", "tags": ["新硬件软件技术"], "difficulty": null, "terms": "2026 秋", "units": "3", "search": "CS 349H Software Techniques for Emerging Hardware Platforms (EE 349) 新硬件软件技术 为 FPGA、加速器等新型硬件写高效软件。 Research seminar on software techniques for emerging computational substrates with guest lectures from hardware designers from research and industry. This seminar explores the benefits of novel hardware technologies, the challenges gating broad adoption of these technologies, and how software techniques can help mitigate these challenges and improve the usability of these hardware platforms. Note that the computational substrates discussed vary depending on the semester. Topics covered include: In-memory computing platforms, dynamical system-solving mixed-signal devices, exible and bendable electronics, neuromorphic computers, intermittent computing platforms, ReRAMs, DNA-based storage, and optical computing platforms. Prerequisites: CS107 or CS107E (required) and EE180 (recommended)."}, {"id": "CS 528", "slug": "cs-528-machine-learning-systems-seminar", "zh": "ML 系统 seminar", "cat": "ML 系统与硬件", "type": "ext", "one": "ML 系统与基础设施前沿论文讨论。", "card_desc": "ML 系统与基础设施前沿论文讨论。", "tags": ["ML 系统 seminar"], "difficulty": null, "terms": "2026–27 未排课", "units": "1", "search": "CS 528 Machine Learning Systems Seminar ML 系统 seminar ML 系统与基础设施前沿论文讨论。 Machine learning is driving exciting changes and progress in computing systems. What does the ubiquity of machine learning mean for how people build and deploy systems and applications? What challenges does industry face when deploying machine learning systems in the real world, and how can new system designs meet those challenges? In this weekly talk series, we will invite speakers working at the frontier of machine learning systems, and focus on how machine learning changes the modern programming stack. Topics will include programming models for ML, infrastructure to support ML applications such as ML Platforms, debugging, parallel computing, and hardware for ML. May be repeated for credit."}, {"id": "CS 131", "slug": "cs-131-computer-vision-foundations-and-applications", "zh": "计算机视觉基础", "cat": "视觉、图形与生成", "type": "ext", "one": "图像形成、特征、几何与识别，CV 的本科入门课。", "card_desc": "图像形成、特征、几何与识别，CV 的本科入门课。", "tags": ["计算机视觉基础"], "difficulty": null, "terms": "2027 冬", "units": "3–4", "search": "CS 131 Computer Vision: Foundations and Applications 计算机视觉基础 图像形成、特征、几何与识别，CV 的本科入门课。 Computer Vision technologies are transforming automotive, healthcare, manufacturing, agriculture and many other sections. Today, household robots can navigate spaces and perform duties, search engines can index billions of images and videos, algorithms can diagnose medical images for diseases, and smart cars can see and drive safely. Lying in the heart of these modern AI applications are computer vision technologies that can perceive, understand, and reconstruct the complex visual world. This course is designed for students who are interested in learning about the fundamental principles and important applications of Computer Vision. This course will introduce a number of fundamental concepts in image processing and expose students to a number of real-world applications. It will guide students through a series of projects to implement cutting-edge algorithms. There will be optional discussion sections on Fridays. Prerequisites: Students should be familiar with Python, Calculus &amp; Linear Algebra."}, {"id": "CS 231A", "slug": "cs231a-computer-vision-3d", "zh": "计算机视觉：从 3D 感知到重建", "cat": "视觉、图形与生成", "type": "core", "one": "从相机模型到 3D 重建的计算机视觉：几何为主，深度学习为辅。", "card_desc": "从相机模型到 3D 重建的计算机视觉：几何为主，深度学习为辅。", "tags": ["CV", "3D", "几何", "重建"], "difficulty": 4, "terms": "2026–27 未排课", "units": "3–4", "search": "CS 231A 计算机视觉：从 3D 感知到重建 Computer Vision: From 3D Perception to 3D Reconstruction and Beyond 从相机模型到 3D 重建的计算机视觉：几何为主，深度学习为辅。 CV 3D 几何 重建 Introduction Camera Models Camera Models II and Camera Calibration Single View Metrology Epipolar Geometry Stereo Systems Structure from Motion Active Stereo & Volumetric Stereo Fitting and Matching Representations & Representation Learning Monocular Depth Estimation & Feature Tracking Learning-based Stereo & Monocular Depth Estimation Optical and Scene Flow Optimal Estimation Optimal Estimation Cont. Neural Radiance Fields Gaussian Splatting Guest Lecture camera model SfM stereo NeRF Gaussian splatting"}, {"id": "CS 236G", "slug": "cs236g-generative-adversarial-networks", "zh": "生成对抗网络", "cat": "视觉、图形与生成", "type": "core", "one": "GAN 专课：从原理到 SOTA，覆盖训练稳定性、评估和偏见。", "card_desc": "GAN 专课：从原理到 SOTA，覆盖训练稳定性、评估和偏见。", "tags": ["GAN", "生成模型", "视觉"], "difficulty": 3, "terms": "2026–27 未排课", "units": "3", "search": "CS 236G 生成对抗网络 Generative Adversarial Networks GAN 专课：从原理到 SOTA，覆盖训练稳定性、评估和偏见。 GAN 生成模型 视觉"}, {"id": "CS 348I", "slug": "cs348i-computer-graphics-in-the-era-of-ai", "zh": "AI 时代的计算机图形学", "cat": "视觉、图形与生成", "type": "core", "one": "AI 时代的图形学：神经渲染、可微渲染、材质/纹理、动画、物理仿真。", "card_desc": "AI 时代的图形学：神经渲染、可微渲染、材质/纹理、动画、物理仿真。", "tags": ["图形", "神经渲染", "3D", "生成"], "difficulty": 4, "terms": "2026–27 未排课", "units": "3–4", "search": "CS 348I AI 时代的计算机图形学 Computer Graphics in the Era of AI AI 时代的图形学：神经渲染、可微渲染、材质/纹理、动画、物理仿真。 图形 神经渲染 3D 生成"}, {"id": "CS 348K", "slug": "cs-348k-visual-computing-systems", "zh": "视觉计算系统", "cat": "视觉、图形与生成", "type": "ext", "one": "图像/视频处理的系统与硬件协同设计。", "card_desc": "图像/视频处理的系统与硬件协同设计。", "tags": ["视觉计算系统"], "difficulty": null, "terms": "2027 春", "units": "3–4", "search": "CS 348K Visual Computing Systems 视觉计算系统 图像/视频处理的系统与硬件协同设计。 Visual computing tasks such as computational photography, image/video understanding, and real-time 3D graphics are key responsibilities of modern computer systems ranging from sensor-rich smart phones, autonomous robots, and large data centers. These workloads demand exceptional system efficiency and this course examines the key ideas, techniques, and challenges associated with the design of parallel, heterogeneous systems that execute and accelerate visual computing applications. This course is intended for graduate and advanced undergraduate-level students interested in architecting efficient graphics, image processing, and computer vision systems (both new hardware architectures and domain-optimized programming frameworks) and for students in graphics, vision, and ML that seek to understand throughput computing concepts so they can develop scalable algorithms for these platforms. Students will perform daily research paper readings, complete simple programming assignments, and compete a self-selected term project. Prerequisites: CS 107 or equivalent. Highly recommended: Parallel Computing (CS149) or Computer Architecture (EE 282). Students will benefit from some background in deep learning (CS 230, CS 231N), computer vision (CS 231A), digital image processing (CS 232) or computer graphics (CS248)."}, {"id": "CS 348N", "slug": "cs348n-neural-models-for-3d-geometry", "zh": "3D 几何的神经模型", "cat": "视觉、图形与生成", "type": "core", "one": "3D 几何的神经表示：点云、网格、implicit field、3D 生成。", "card_desc": "3D 几何的神经表示：点云、网格、implicit field、3D 生成。", "tags": ["3D", "生成模型", "图形", "NeRF"], "difficulty": 4, "terms": "2026–27 未排课", "units": "3", "search": "CS 348N 3D 几何的神经模型 Neural Models for 3D Geometry 3D 几何的神经表示：点云、网格、implicit field、3D 生成。 3D 生成模型 图形 NeRF"}, {"id": "CS 448I", "slug": "cs448i-computational-imaging", "zh": "计算成像", "cat": "视觉、图形与生成", "type": "core", "one": "计算成像：从卷积/去噪到逆问题、波光学、端到端光学-算法联合优化。", "card_desc": "计算成像：从卷积/去噪到逆问题、波光学、端到端光学-算法联合优化。", "tags": ["成像", "逆问题", "光学", "CV"], "difficulty": 4, "terms": "2027 冬", "units": "3", "search": "CS 448I 计算成像 Computational Imaging (EE 367) 计算成像：从卷积/去噪到逆问题、波光学、端到端光学-算法联合优化。 成像 逆问题 光学 CV"}, {"id": "CS 468", "slug": "cs468-topics-in-geometric-computing", "zh": "几何计算专题：3D/4D 基础模型", "cat": "视觉、图形与生成", "type": "core", "one": "几何计算专题课，近年聚焦 3D/4D 基础模型。", "card_desc": "几何计算专题课，近年聚焦 3D/4D 基础模型。", "tags": ["几何", "3D", "图形", "专题"], "difficulty": 4, "terms": "2026–27 未排课", "units": "3", "search": "CS 468 几何计算专题：3D/4D 基础模型 Topics in Geometric Computing - 3D and 4D Foundation Models 几何计算专题课，近年聚焦 3D/4D 基础模型。 几何 3D 图形 专题"}, {"id": "CS 470", "slug": "cs-470-music-and-ai-music-356", "zh": "音乐与 AI", "cat": "视觉、图形与生成", "type": "ext", "one": "生成、检索与音乐理解中的 ML 方法。", "card_desc": "生成、检索与音乐理解中的 ML 方法。", "tags": ["音乐与 AI"], "difficulty": null, "terms": "2026–27 未排课", "units": "3–4", "search": "CS 470 Music and AI (MUSIC 356) 音乐与 AI 生成、检索与音乐理解中的 ML 方法。 How do we make music with artificial intelligence? What does it mean to do so (and is it even a good idea)? How might we design systems that balance machine automation and human interaction? More broadly, how do we want to live with our technologies? Are there - and ought there be - limits to using AI for art? (And what is Art, anyway?) In this &quot;critical making&quot; course, students will learn practical tools and techniques for AI-mediated music creation, engineer software systems incorporating AI, HCI and Music, and critically reflect on the aesthetic and ethical dimensions of technology."}, {"id": "CS 523", "slug": "cs-523-research-seminar-in-computer-vision-x", "zh": "CV + X seminar", "cat": "视觉、图形与生成", "type": "ext", "one": "视觉与其它领域交叉的研究 seminar。", "card_desc": "视觉与其它领域交叉的研究 seminar。", "tags": ["CV + X seminar"], "difficulty": null, "terms": "2026–27 未排课", "units": "1–2", "search": "CS 523 Research Seminar in Computer Vision + X CV + X seminar 视觉与其它领域交叉的研究 seminar。 With advances in deep learning, computer vision (CV) has been transforming all sorts of domains, including healthcare, human-computer interaction, transportation, art, sustainability, and so much more. In this seminar, we investigate its far-reaching applications, with a different theme chosen as the focus each quarter (e.g. the inaugural quarter was CV + Healthcare; the theme for the quarter will be listed on the class syllabus). Throughout the quarter, we deeply examine these themes in CV + X research through weekly intimate discussions with researchers from academia and industry labs who conduct research at the center of CV and other domains. Each week, students will read and prepare questions and reflections on an assigned paper authored by that week's speaker. We highly encourage students who are interested in taking an interactive, deep dive into CV research literature to apply. While there are no hard requirements, we strongly suggest having the background and fluency necessary to read and analyze AI research papers (thus MATH 51 or linear algebra, and at least one of CS 231x, 224x, 221, 229, 230, 234, 238, AI research experience for CV and AI fundamentals may be helpful)."}, {"id": "CS 123", "slug": "cs-123-a-hands-on-introduction-to-building-ai-enabled-robots", "zh": "动手做 AI 机器人", "cat": "机器人、具身智能", "type": "ext", "one": "从零搭一个能感知、决策、行动的 AI 机器人。", "card_desc": "从零搭一个能感知、决策、行动的 AI 机器人。", "tags": ["动手做 AI 机器人"], "difficulty": null, "terms": "2026 秋", "units": "3", "search": "CS 123 A Hands-On Introduction to Building AI-Enabled Robots 动手做 AI 机器人 从零搭一个能感知、决策、行动的 AI 机器人。 This course offers a hands-on introduction to AI-powered robotics. Unlike most introductory robotics courses, students will learn essential robotics concepts by constructing a quadruped robot from scratch and training it to perform real-world tasks. The course covers a broad range of topics critical to robot learning, including motor control, forward and inverse kinematics, system identification, simulation, and reinforcement learning. Through weekly labs, students will construct a pair of tele-operated robot arms with haptic feedback, program a robot arm to learn self-movement, and ultimately create and program an agile robot quadruped named Pupper. In the final four weeks, students will undertake an open-ended project using Pupper as a platform, such as instructing it to walk using reinforcement learning, developing a vision system to allow Pupper to play fetch, or redesigning the hardware to enhance the robot's agility. Note: CS123 strives to achieve a balanced distribution of seniority across the undergrad student body. Within the first 100 registrations, enrollment of students will follow a lottery that balances such distribution amongst undergraduates. Please use the form below to enroll in the class. The form will be open on 9/8/2025 9:00AM Pacific Time. Please use this form to apply: https://tinyurl.com/cs123-2025fall and check out our website for more information: https://cs123-stanford.readthedocs.io/"}, {"id": "CS 223A", "slug": "cs223a-introduction-to-robotics", "zh": "机器人学导论", "cat": "机器人、具身智能", "type": "core", "one": "机器人学基础：运动学、静力学、动力学、规划、控制。", "card_desc": "机器人学基础：运动学、静力学、动力学、规划、控制。", "tags": ["机器人", "运动学", "控制", "基础"], "difficulty": 4, "terms": "2027 冬", "units": "3", "search": "CS 223A 机器人学导论 Introduction to Robotics (ME 320) 机器人学基础：运动学、静力学、动力学、规划、控制。 机器人 运动学 控制 基础"}, {"id": "CS 225A", "slug": "cs225a-experimental-robotics", "zh": "实验机器人学", "cat": "机器人、具身智能", "type": "core", "one": "实验机器人：动手做机械臂的运动学、动力学、控制、柔顺和碰撞避免。", "card_desc": "实验机器人：动手做机械臂的运动学、动力学、控制、柔顺和碰撞避免。", "tags": ["机器人", "实验", "控制", "项目"], "difficulty": 4, "terms": "2027 春", "units": "3", "search": "CS 225A 实验机器人学 Experimental Robotics 实验机器人：动手做机械臂的运动学、动力学、控制、柔顺和碰撞避免。 机器人 实验 控制 项目"}, {"id": "CS 227A", "slug": "cs227a-robot-perception", "zh": "机器人感知", "cat": "机器人、具身智能", "type": "core", "one": "机器人感知：视觉/触觉/声学传感器 + 算法，在仿真里搭一套 vision-based 机器人系统。", "card_desc": "机器人感知：视觉/触觉/声学传感器 + 算法，在仿真里搭一套 vision-based 机器人系统。", "tags": ["机器人", "感知", "视觉", "仿真"], "difficulty": 4, "terms": "2026 秋", "units": "3–4", "search": "CS 227A 机器人感知 Robot Perception (EE 227) 机器人感知：视觉/触觉/声学传感器 + 算法，在仿真里搭一套 vision-based 机器人系统。 机器人 感知 视觉 仿真"}, {"id": "CS 237A", "slug": "cs237a-principles-of-robot-autonomy-i", "zh": "机器人自主性原理 I", "cat": "机器人、具身智能", "type": "core", "one": "自主机器人 I：感知、定位、SLAM、非线性控制、运动规划、POMDP。", "card_desc": "自主机器人 I：感知、定位、SLAM、非线性控制、运动规划、POMDP。", "tags": ["机器人", "SLAM", "规划", "ROS"], "difficulty": 4, "terms": "2026 秋", "units": "3", "search": "CS 237A 机器人自主性原理 I Principles of Robot Autonomy I (AA 274A, EE 260A, ME 274A) 自主机器人 I：感知、定位、SLAM、非线性控制、运动规划、POMDP。 机器人 SLAM 规划 ROS"}, {"id": "CS 237B", "slug": "cs237b-principles-of-robot-autonomy-ii", "zh": "机器人自主性原理 II", "cat": "机器人、具身智能", "type": "core", "one": "自主机器人 II：RL/最优控制、操作、模仿学习、人机交互、系统架构。", "card_desc": "自主机器人 II：RL/最优控制、操作、模仿学习、人机交互、系统架构。", "tags": ["机器人", "操作", "RL", "模仿学习"], "difficulty": 4, "terms": "2026–27 未排课", "units": "3–4", "search": "CS 237B 机器人自主性原理 II Principles of Robot Autonomy II (AA 174B, AA 274B, EE 260B, ME 274B) 自主机器人 II：RL/最优控制、操作、模仿学习、人机交互、系统架构。 机器人 操作 RL 模仿学习"}, {"id": "CS 333", "slug": "cs-333-algorithms-for-interactive-robotics", "zh": "交互机器人算法", "cat": "机器人、具身智能", "type": "ext", "one": "运动规划、抓取与人机交互中的算法问题。", "card_desc": "运动规划、抓取与人机交互中的算法问题。", "tags": ["交互机器人算法"], "difficulty": null, "terms": "2026–27 未排课", "units": "3–4", "search": "CS 333 Algorithms for Interactive Robotics 交互机器人算法 运动规划、抓取与人机交互中的算法问题。 AI agents need to collaborate and interact with humans in many different settings such as bots operating on social media and crowdsourcing platforms, AI assistants brokering transactions on electronic marketplaces, autonomous vehicles driving alongside humans, or robots interacting with and assisting humans in homes. Our goal in this class is to learn about and design algorithms that enable robots and AI agents to reason about their actions, interact with one another, the humans, and the environment they live in, as well as plan safe strategies that humans can trust and rely on. This is a project-based graduate course that studies algorithms in robotics, machine learning, and control theory, which can improve the state-of-the-art human-AI systems. nnRecommended: Introductory course in AI (CS 221) and Machine Learning (CS 229)."}, {"id": "CS 339R", "slug": "cs-339r-collaborative-robotics-me-326", "zh": "协作机器人", "cat": "机器人、具身智能", "type": "ext", "one": "人机协作、共享控制与安全交互。", "card_desc": "人机协作、共享控制与安全交互。", "tags": ["协作机器人"], "difficulty": null, "terms": "2027 冬", "units": "3", "search": "CS 339R Collaborative Robotics (ME 326) 协作机器人 人机协作、共享控制与安全交互。 This course focuses on how robots can be effective teammates with other robots and human partners. Concepts and tools will be reviewed for characterizing task objectives, robot perception and control, teammate behavioral modeling, inter-agent communication, and team consensus. We will consider the application of these tools to robot collaborators, wearable robotics, and the latest applications in the relevant literature. This will be a project-based graduate course, with the implementation of algorithms in either python or C++."}, {"id": "CS 345", "slug": "cs-345-building-ai-enabled-robots", "zh": "构建 AI 机器人", "cat": "机器人、具身智能", "type": "ext", "one": "把感知、规划与控制集成成完整机器人系统。", "card_desc": "把感知、规划与控制集成成完整机器人系统。", "tags": ["构建 AI 机器人"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CS 345 Building AI-Enabled Robots 构建 AI 机器人 把感知、规划与控制集成成完整机器人系统。 This course offers a hands-on experiences in building AI-powered robotic quadrupeds. Students will learn the state-of-the-art algorithms and techniques in robot learning and apply them in practice to build a fully functional quadruped. Specifically, the course consists of role-playing paper discussion and hands-on labs. A set of carefully curated papers will be selected at the beginning of the quarter. Each week, everyone reads the same paper, but a small number of student presenters take on specific roles for that paper. The role defines the lens through which the student reads the paper and what they bring to the discussion. Examples of roles include the journalist who summarizes the paper and its contributions based on facts, the paper reviewer who provides critical and insightful criticisms, and the archaeologist who determines where this paper sits in the context of previous and subsequent work. The lab portion of the course focuses on hands-on robot building, programming/training, and evaluation. Students will work in groups of four to develop their quadruped for their sole project in this course. A detailed weekly plan will be proposed and reviewed at the beginning of the quarter. Through weekly labs, students will work toward their final goals of creating an intelligent companion robot dog.Prerequisites: CS123 (or other approved robotics courses), CS107, MATH51"}, {"id": "CS 381", "slug": "cs381-sensorimotor-learning-for-embodied-agents", "zh": "具身智能的感知运动学习", "cat": "机器人、具身智能", "type": "core", "one": "具身智能的 sensorimotor learning：从原始感知到决策，持续适应物理世界。", "card_desc": "具身智能的 sensorimotor learning：从原始感知到决策，持续适应物理世界。", "tags": ["具身智能", "机器人", "研究", "VLA"], "difficulty": 5, "terms": "2027 冬", "units": "3", "search": "CS 381 具身智能的感知运动学习 Sensorimotor Learning for Embodied Agents (EE 381) 具身智能的 sensorimotor learning：从原始感知到决策，持续适应物理世界。 具身智能 机器人 研究 VLA"}, {"id": "CS 270", "slug": "cs-270-modeling-biomedical-systems-bmds-210", "zh": "生物医学系统建模", "cat": "AI for Science 与医疗", "type": "ext", "one": "用微分方程、统计与 ML 建模生理系统。", "card_desc": "用微分方程、统计与 ML 建模生理系统。", "tags": ["生物医学系统建模"], "difficulty": null, "terms": "2027 春", "units": "3", "search": "CS 270 Modeling Biomedical Systems (BMDS 210) 生物医学系统建模 用微分方程、统计与 ML 建模生理系统。 Biomedical systems translate complex biological and medical data into computable formats that can be used for tasks such as diagnosis, decision support, or drug discovery. At the core of these systems is the challenge of creating fully computable, machine-actionable models of biomedical information so that knowledge can be shared and reused across different applications. This course explores methods for modeling biomedical systems, including topics in knowledge representation, controlled terminologies, ontologies, interoperability, and symbolic AI. Students will acquire hands-on experiences with several systems and tools, such as Prot&eacute;g&eacute;, Fast Healthcare Interoperability Resources (FHIR), and semantic web technologies. Prerequisites: CS106A or equivalent. Basic familiarity with programming, probability, and logic are helpful for taking this course."}, {"id": "CS 271", "slug": "cs-271-algorithmic-foundations-for-artificial-intelligence-in-healthcare-bmds-270", "zh": "医疗 AI 算法基础", "cat": "AI for Science 与医疗", "type": "ext", "one": "医疗数据、临床预测任务与医疗 AI 的算法和评估。", "card_desc": "医疗数据、临床预测任务与医疗 AI 的算法和评估。", "tags": ["医疗 AI 算法基础"], "difficulty": null, "terms": "2026–27 未排课", "units": "3–4", "search": "CS 271 Algorithmic Foundations for Artificial Intelligence in Healthcare (BMDS 270) 医疗 AI 算法基础 医疗数据、临床预测任务与医疗 AI 的算法和评估。 Healthcare is one of the most exciting application domains of artificial intelligence, with transformative potential in areas ranging from medical image analysis to electronic health records-based prediction and precision medicine. This course will involve a deep dive into recent advances in AI in healthcare, focusing in particular on deep learning approaches for healthcare problems. We will start from foundations of neural networks, and then study cutting-edge deep learning models in the context of a variety of healthcare data including image, text, multimodal and time-series data. In the latter part of the course, we will cover advanced topics on open challenges of integrating AI in a societal application such as healthcare, including interpretability, robustness, privacy and fairness. The course aims to provide students from diverse backgrounds with both conceptual understanding and practical grounding of cutting-edge research on AI in healthcare. Prerequisites: Proficiency in Python or ability to self-learn; familiarity with machine learning and basic calculus, linear algebra, statistics; familiarity with deep learning highly recommended (e.g. prior experience training a deep learning model)."}, {"id": "CS 273B", "slug": "cs273b-deep-learning-in-genomics", "zh": "基因组与生物医学中的深度学习", "cat": "AI for Science 与医疗", "type": "core", "one": "基因组与生物医学的深度学习：监督/无监督/生成模型 + 可解释性。", "card_desc": "基因组与生物医学的深度学习：监督/无监督/生成模型 + 可解释性。", "tags": ["AI4Bio", "基因组", "医疗", "深度学习"], "difficulty": 4, "terms": "2027 春", "units": "3", "search": "CS 273B 基因组与生物医学中的深度学习 Deep Learning in Genomics and Biomedicine (BMDS 273, GENE 236) 基因组与生物医学的深度学习：监督/无监督/生成模型 + 可解释性。 AI4Bio 基因组 医疗 深度学习"}, {"id": "CS 277", "slug": "cs277-foundation-models-for-healthcare", "zh": "医疗基础模型", "cat": "AI for Science 与医疗", "type": "core", "one": "医疗基础模型：NLP/CV/多模态 FM 的训练、评估、部署。", "card_desc": "医疗基础模型：NLP/CV/多模态 FM 的训练、评估、部署。", "tags": ["医疗", "Foundation Model", "多模态"], "difficulty": 3, "terms": "2027 冬", "units": "3", "search": "CS 277 医疗基础模型 Foundation Models for Healthcare (BMDS 271, RAD 271) 医疗基础模型：NLP/CV/多模态 FM 的训练、评估、部署。 医疗 Foundation Model 多模态 Course Introduction & Overview of Foundation Models Introduction to LLMs Agentic Systems Evaluation of LLMs and Agents; MedArena Evaluation of LLMs (Part 2) Retrieval Augmented Generation; Mixture of Experts Inference Scaling and Reasoning Vision-Language Models Mechanistic Interpretability of VLMs Generative VLMs for Vision Generative VLMs for Text Foundation Models for Segmentation Regulation and Deployment: EchoNet Case Study SleepFM: Multimodal Foundation Model of Sleep Advanced Architectures EMR Foundation Models Ethics of Foundation Models Final Presentations medical foundation model VLM EHR RAG clinical"}, {"id": "CS 279", "slug": "cs279-computational-biology", "zh": "计算生物学：生物分子与细胞的结构和组织", "cat": "AI for Science 与医疗", "type": "core", "one": "计算生物学：蛋白结构预测/设计、分子模拟、药物筛选、显微图像分析。", "card_desc": "计算生物学：蛋白结构预测/设计、分子模拟、药物筛选、显微图像分析。", "tags": ["AI4Bio", "蛋白", "药物发现", "模拟"], "difficulty": 4, "terms": "2026 秋", "units": "3", "search": "CS 279 计算生物学：生物分子与细胞的结构和组织 Computational Biology: Structure and Organization of Biomolecules and Cells (BIOE 279, BIOPHYS 279, BMDS 245, CME 279) 计算生物学：蛋白结构预测/设计、分子模拟、药物筛选、显微图像分析。 AI4Bio 蛋白 药物发现 模拟 Introduction Biomolecular structure Energy functions & their relationship to molecular conformation Molecular dynamics simulation Protein structure prediction (AlphaFold etc.) Fourier transforms and convolution Image Analysis Microscopy Diffusion and cellular-level simulation Protein design Project topics Ligand docking and virtual screening X-ray crystallography Cryo-electron microscopy Review protein AlphaFold molecular dynamics cryo-EM drug design"}, {"id": "CS 286", "slug": "cs286-advanced-cv-and-biomedicine", "zh": "计算机视觉与生物医学进阶", "cat": "AI for Science 与医疗", "type": "core", "one": "CV + 生物医学进阶：视觉基础模型、扩散/生成、vision-language 在医疗的落地。", "card_desc": "CV + 生物医学进阶：视觉基础模型、扩散/生成、vision-language 在医疗的落地。", "tags": ["医疗", "CV", "Foundation Model", "研究"], "difficulty": 4, "terms": "2026 秋", "units": "3", "search": "CS 286 计算机视觉与生物医学进阶 Advanced Topics in Computer Vision and Biomedicine (BMDS 276) CV + 生物医学进阶：视觉基础模型、扩散/生成、vision-language 在医疗的落地。 医疗 CV Foundation Model 研究"}, {"id": "CS 287", "slug": "cs287-data-centric-ai-for-healthcare", "zh": "医疗 Data-Centric AI", "cat": "AI for Science 与医疗", "type": "core", "one": "医疗 Data-Centric AI：数据怎么产生、偏见/缺失/泄漏怎么毁掉模型，以及怎么修。", "card_desc": "医疗 Data-Centric AI：数据怎么产生、偏见/缺失/泄漏怎么毁掉模型，以及怎么修。", "tags": ["医疗", "数据", "Data-Centric", "鲁棒性"], "difficulty": 3, "terms": "2027 冬", "units": "3", "search": "CS 287 医疗 Data-Centric AI Data Centric AI for Healthcare (BMDS 218) 医疗 Data-Centric AI：数据怎么产生、偏见/缺失/泄漏怎么毁掉模型，以及怎么修。 医疗 数据 Data-Centric 鲁棒性"}, {"id": "CS 322", "slug": "cs-322-triangulating-intelligence-melding-neuroscience-psychology-and-ai-psych-225", "zh": "神经科学 × AI", "cat": "AI for Science 与医疗", "type": "ext", "one": "用神经科学与心理学 triangulate 智能的本质。", "card_desc": "用神经科学与心理学 triangulate 智能的本质。", "tags": ["神经科学 × AI"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CS 322 Triangulating Intelligence: Melding Neuroscience, Psychology, and AI (PSYCH 225) 神经科学 × AI 用神经科学与心理学 triangulate 智能的本质。 This course will cover both classic findings and the latest research progress on the intersection of cognitive science, neuroscience, and artificial intelligence: How does the study of minds and machines inform and guide each other? What are the assumptions, representations, or learning mechanisms that are shared (across multiple disciplines, and what are different? How can we build a synergistic partnership between cognitive psychology, neuroscience, and artificial intelligence? We will focus on object perception and social cognition (human capacities, especially in infancy and early childhood) and the ways in which these capacities are formalized and reverse-engineered (computer vision, reinforcement learning). Through paper reading and review, discussion, and the final project, students will learn the common foundations shared behind neuroscience, cognitive science, and AI research and leverage them to develop their own research project in these areas. Recommended prerequisites: PSYCH 1, PSYCH 24/SYMSYS 1/CS 24, CS 221, CS 231N"}, {"id": "CS 339N", "slug": "cs-339n-machine-learning-methods-for-neural-data-analysis-nbio-220-stats-220-stats-320", "zh": "神经数据 ML", "cat": "AI for Science 与医疗", "type": "ext", "one": "spike sorting、行为追踪与神经时间序列建模。", "card_desc": "spike sorting、行为追踪与神经时间序列建模。", "tags": ["神经数据 ML"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CS 339N Machine Learning Methods for Neural Data Analysis (NBIO 220, STATS 220, STATS 320) 神经数据 ML spike sorting、行为追踪与神经时间序列建模。 With modern high-density electrodes and optical imaging techniques, neuroscientists routinely measure the activity of hundreds, if not thousands, of cells simultaneously. Coupled with high-resolution behavioral measurements, genetic sequencing, and connectomics, these datasets offer unprecedented opportunities to learn how neural circuits function. This course will study statistical machine learning methods for analyzing such datasets, including: spike sorting, calcium deconvolution, and voltage smoothing techniques for extracting relevant signals from raw data; markerless tracking methods for estimating animal pose in behavioral videos; network models for connectomics and fMRI data; state space models for analysis of high-dimensional neural and behavioral time-series; point process models of neural spike trains; and deep learning methods for neural encoding and decoding. We will develop the theory behind these models and algorithms and then apply them to real datasets in the homeworks and final project."}, {"id": "CS 375", "slug": "cs375-large-scale-neural-network-modeling-for-neuroscience", "zh": "面向神经科学的大规模神经网络建模", "cat": "AI for Science 与医疗", "type": "core", "one": "用大规模神经网络建模大脑：视觉/听觉/运动/语言/决策的“人机收敛进化”。", "card_desc": "用大规模神经网络建模大脑：视觉/听觉/运动/语言/决策的“人机收敛进化”。", "tags": ["NeuroAI", "计算神经", "AI4Science"], "difficulty": 4, "terms": "2027 冬", "units": "3", "search": "CS 375 面向神经科学的大规模神经网络建模 Large-Scale Neural Network Modeling for Neuroscience (PSYCH 249) 用大规模神经网络建模大脑：视觉/听觉/运动/语言/决策的“人机收敛进化”。 NeuroAI 计算神经 AI4Science Introduction to NeuroAI Visual Systems Neuroscience Background DNN Models of the Visual System — Part 1 Model-Brain Mapping Methods DNN Models of the Visual System — Part 2 Unsupervised Learning and the Brain Modeling Infant Development (Cliona O'Doherty) Recurrent Models of Vision The Enigma Project (Andreas Tolias) Auditory and Somatosensory Models Decision Making (Andrew Saxe) Navigation, Memory, and the MEC Models of Agents (Aran Nayebi) The Motor System Dynamical Systems in the Brain (Scott Lindermann) Language, LLMs, and the Brain (Greta Tuckute) Models of Brain Evolution (Tony Zador) Functional Organization and Learning Rules in the Brain Project Presentations NeuroAI visual system brain model-brain mapping"}, {"id": "CS 522", "slug": "cs-522-seminar-in-artificial-intelligence-in-healthcare", "zh": "医疗 AI seminar", "cat": "AI for Science 与医疗", "type": "ext", "one": "医院、产业与投资人视角的医疗 AI 前沿。", "card_desc": "医院、产业与投资人视角的医疗 AI 前沿。", "tags": ["医疗 AI seminar"], "difficulty": null, "terms": "2026 秋", "units": "1", "search": "CS 522 Seminar in Artificial Intelligence in Healthcare 医疗 AI seminar 医院、产业与投资人视角的医疗 AI 前沿。 Artificial intelligence is poised to make radical changes in healthcare, transforming areas such as diagnosis, genomics, surgical robotics, and drug discovery. In the coming years, artificial intelligence has the potential to lower healthcare costs, identify more effective treatments, and facilitate prevention and early detection of diseases. This class is a seminar series featuring prominent researchers, physicians, entrepreneurs, and venture capitalists, all sharing their thoughts on the future of healthcare. We highly encourage students of all backgrounds to enroll (no AI/healthcare background necessary). Speakers and more at https://tinyurl.com/cs522-stanford"}, {"id": "CS 524", "slug": "cs-524-ai-for-science", "zh": "AI for Science", "cat": "AI for Science 与医疗", "type": "ext", "one": "AlphaFold、GNoME 等科学发现中的 ML 主题。", "card_desc": "AlphaFold、GNoME 等科学发现中的 ML 主题。", "tags": ["AI for Science"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CS 524 AI for Science AI for Science AlphaFold、GNoME 等科学发现中的 ML 主题。 AI is transforming scientific discovery - from protein structures prediction, to new materials discovery, to plasma control. This graduate-level seminar surveys the emerging discipline of AI for Science, emphasizing the recurring ML-theoretic themes most salient to scientific regimes: e.g., multi-scale modeling, multi-modal architectures, differentiable simulation, and inference - time reasoning. Weekly meetings pair a classical milestone (e.g., AlphaFold, AlphaGo) with a recent breakthrough (e.g., GNoME, GraphCast, TAE's Optometrist algorithm). Students read, present, and critique papers, replicate key results in lightweight coding labs, and pursue an open - ended research project targeting new science or tooling."}, {"id": "CS 525", "slug": "cs-525-data-for-ai", "zh": "Data for AI", "cat": "AI for Science 与医疗", "type": "ext", "one": "训练数据的筛选、去重、合成、归因与版权。", "card_desc": "训练数据的筛选、去重、合成、归因与版权。", "tags": ["Data for AI"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CS 525 Data for AI Data for AI 训练数据的筛选、去重、合成、归因与版权。 CS525 surveys the landscape of data for AI with a focus on contemporary learning problems such as training language models or multimodal models. Students will learn about important datasets and common data processing methods including filtering and deduplication. Further topics will include synthetic data, data attribution, and environments for reinforcement learning. The course will also cover ethical and legal aspects of training data such as copyright and privacy. Over the course of the class, students will build a training set for a learning problem of their choice. The class will consist of faculty lectures, student presentations, and guest lectures."}, {"id": "EE 292M", "slug": "ee-292m-ai-augmented-research-and-development-foundations-and-practice", "zh": "AI 增强研发", "cat": "AI for Science 与医疗", "type": "ext", "one": "把 LLM、RAG、agent 纳入科研工作流并做验证。", "card_desc": "把 LLM、RAG、agent 纳入科研工作流并做验证。", "tags": ["AI 增强研发"], "difficulty": null, "terms": "2026 秋", "units": "3", "search": "EE 292M AI-Augmented Research and Development: Foundations and Practice AI 增强研发 把 LLM、RAG、agent 纳入科研工作流并做验证。 Al-Augmented Research teaches graduate students to integrate Al tools into scientific research with the same rigor they apply to experimental design and statistical inference. The course treats the use of large language models and prompting as an engineering discipline. It teaches retrieval-augmented generation, Al-assisted software development, agentic systems, human-Al collaboration patterns, and evaluation frameworks for detecting and analyzing Al failures. Students build working systems on their own research data throughout the course, culminating in a capstone project that produces a deliverable for their research group. The emphasis is on verification, failure analysis, and developing the professional judgment to know when Al helps, when it hurts, and when to set it aside entirely."}, {"id": "EE 292R", "slug": "ee292r-ai-and-data-for-science", "zh": "AI 与数据驱动的科学", "cat": "AI for Science 与医疗", "type": "core", "one": "AI4Science 前沿讲座：每周一位 Stanford 教授讲 AI/数据如何推进自己的科学领域。", "card_desc": "AI4Science 前沿讲座：每周一位 Stanford 教授讲 AI/数据如何推进自己的科学领域。", "tags": ["AI4Science", "讲座", "跨学科"], "difficulty": 1, "terms": "2026 秋 / 2027 冬 / 2027 春", "units": "1", "search": "EE 292R AI 与数据驱动的科学 AI and Data for Science (CS 292, PSYCH 292R, STATS 282) AI4Science 前沿讲座：每周一位 Stanford 教授讲 AI/数据如何推进自己的科学领域。 AI4Science 讲座 跨学科 Stephen Baccus — Mechanistically interpretable models of computation in the early visual system Gordon Wetzstein — From World Models to World Agents Olivier Gevaert — Multimodal modeling for precision medicine Curtis Langlotz — Training Methods for a Medical Imaging Foundation Model Anshul Kundaje — Decoding regulatory DNA with deep learning models Dan Yamins — Large-Scale Computational Models at the Neuroscience-AI Intersection Ruijiang Li — Multi-Modal Foundation Models for Precision Medicine Alex Pentland — Detecting coordinated behavior across multiple fully encrypted domains Andreas Tolias — Decrypting the Brain with AI Leonidas Guibas — TBA AI4Science science"}, {"id": "PSYCH 209", "slug": "psych-209-neural-network-models-of-cognition", "zh": "认知的神经网络模型", "cat": "AI for Science 与医疗", "type": "ext", "one": "用神经网络建模认知与发展过程。", "card_desc": "用神经网络建模认知与发展过程。", "tags": ["认知的神经网络模型"], "difficulty": null, "terms": "2026–27 未排课", "units": "4", "search": "PSYCH 209 Neural Network Models of Cognition 认知的神经网络模型 用神经网络建模认知与发展过程。 Neural Network models of cognitive and developmental processes in humans and non-human animal models, and the neural basis of these processes. This is a small, hands-on, discussion intensive class in which students read, comment on, and discuss readings about fundamental mathematical and computational principles of neural networks and learn about classical and contemporary applications. Students also carry out exercises in the first four weeks, then undertake projects during the last six weeks of the quarter, focusing on using models to better understand some aspect of human or animal cognition as implemented in the human brain. Intended for students with and interest in human cognition. Prerequisites: computer programming in python, familiarity with differential equations, linear algebra and probability theory, and two or more courses in cognition, cognitive development or cognitive/systems neuroscience. Instructor consent required."}, {"id": "PSYCH 242", "slug": "psych-242-a-modern-explainable-ai-approach-to-theoretical-neuroscience-appphys-293", "zh": "可解释 AI × 理论神经", "cat": "AI for Science 与医疗", "type": "ext", "one": "用可解释性工具反向理解生物与人工网络。", "card_desc": "用可解释性工具反向理解生物与人工网络。", "tags": ["可解释 AI × 理论神经"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "PSYCH 242 A modern explainable AI approach to Theoretical Neuroscience (APPPHYS 293) 可解释 AI × 理论神经 用可解释性工具反向理解生物与人工网络。 Modern artificial intelligence and neuroscience face a common problem: understanding how large distributed nonlinear networks of neurons learn and compute. In both AI and neuroscience we can use common experimental tools involving, observing their input-output behavior, recording the activity of neurons, inspecting the connectivity between them, and causally perturbing them. From these manipulations, how can we reverse engineer neural networks to obtain a conceptual understanding of how computation emerges from them? We will review recent literature in the emerging field of explainable AI that can shed light on these questions, with an eye towards analyzing both biological and artificial networks."}, {"id": "STATS 220", "slug": "stats-220-machine-learning-methods-for-neural-data-analysis-cs-339n-nbio-220-stats-320", "zh": "神经数据 ML", "cat": "AI for Science 与医疗", "type": "ext", "one": "与 CS 339N 交叉的神经数据分析统计方法。", "card_desc": "与 CS 339N 交叉的神经数据分析统计方法。", "tags": ["神经数据 ML"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "STATS 220 Machine Learning Methods for Neural Data Analysis (CS 339N, NBIO 220, STATS 320) 神经数据 ML 与 CS 339N 交叉的神经数据分析统计方法。 With modern high-density electrodes and optical imaging techniques, neuroscientists routinely measure the activity of hundreds, if not thousands, of cells simultaneously. Coupled with high-resolution behavioral measurements, genetic sequencing, and connectomics, these datasets offer unprecedented opportunities to learn how neural circuits function. This course will study statistical machine learning methods for analyzing such datasets, including: spike sorting, calcium deconvolution, and voltage smoothing techniques for extracting relevant signals from raw data; markerless tracking methods for estimating animal pose in behavioral videos; network models for connectomics and fMRI data; state space models for analysis of high-dimensional neural and behavioral time-series; point process models of neural spike trains; and deep learning methods for neural encoding and decoding. We will develop the theory behind these models and algorithms and then apply them to real datasets in the homeworks and final project."}, {"id": "STATS 326", "slug": "stats-326-topics-in-generative-modeling-methods-in-protein-modeling-and-design", "zh": "蛋白生成模型", "cat": "AI for Science 与医疗", "type": "ext", "one": "AlphaFold、扩散模型与蛋白设计前沿论文。", "card_desc": "AlphaFold、扩散模型与蛋白设计前沿论文。", "tags": ["蛋白生成模型"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "STATS 326 Topics in Generative Modeling Methods in Protein Modeling and Design 蛋白生成模型 AlphaFold、扩散模型与蛋白设计前沿论文。 The past five years have brought breakthroughs in computational protein modeling and design as a result of new machine learning methods, especially generative models. This course surveys recent papers on the development and application of methods in this space. The focus is on (1) applications: protein structure prediction (AlphaFold), sequence and structure generation, similarity search, and ensemble modeling, and (2) enabling methods: graph neural networks, transformers, autoencoders, and diffusion models. The course centers on discussion and class participation. An open-ended final project provides an opportunity to relate course topics to thesis interests or to replicate or apply the results of a recent paper. Enrollment is limited to PhD students from any department or requires permission of the instructor."}, {"id": "SYMSYS 123", "slug": "symsys-123-neuroscience-and-artificial-intelligence", "zh": "神经科学 × AI", "cat": "AI for Science 与医疗", "type": "ext", "one": "从神经科学史看 AI，再用 AI 工具研究大脑。", "card_desc": "从神经科学史看 AI，再用 AI 工具研究大脑。", "tags": ["神经科学 × AI"], "difficulty": null, "terms": "2026–27 未排课", "units": "3–4", "search": "SYMSYS 123 Neuroscience and Artificial Intelligence 神经科学 × AI 从神经科学史看 AI，再用 AI 工具研究大脑。 Without neuroscience, none of the artificial intelligence systems that have become part of our daily lives - ChatGPT, Siri, facial recognition - would exist. In this course, we will explore how neuroscience made our contemporary AI world possible and how AI is changing the way scientists study the brain. In the first half of the course, we will walk through key developments in the history of contemporary, neural network-based AI systems and discover how each of them has its roots in scientific discoveries about how the brain works. In the second half of the course, we will learn about how AI tools have themselves become key to neuroscientific research. We will conclude the course by discussing whether neuroscience still has a role to play in the development of contemporary AI systems. Throughout the course, we will cover key scientific papers from both neuroscience and machine learning and gain experience with reading primary scientific literature. Students with a background in Python will have the opportunity to implement the machine learning approaches we discuss themselves, with instructor support. Prerequisites: High school biology, algebra II, some familiarity with matrix algebra"}, {"id": "CS 121", "slug": "cs-121-equity-and-governance-for-artificial-intelligence", "zh": "AI 公平与治理", "cat": "产品、伦理与设计", "type": "ext", "one": "用政策写作与 red-team 实践讨论算法公平、问责与透明。", "card_desc": "用政策写作与 red-team 实践讨论算法公平、问责与透明。", "tags": ["AI 公平与治理"], "difficulty": null, "terms": "2027 冬", "units": "4", "search": "CS 121 Equity and Governance for Artificial Intelligence AI 公平与治理 用政策写作与 red-team 实践讨论算法公平、问责与透明。 This course invites students to argue about the consensus-building processes that shape the development and governance of AI systems. This course requires writing op-eds, policy memos, and research papers, in which students will critically engage AI policy documents while debating norms of fairness, accountability, and transparency. Students will also get hands-on practice evaluating generative AI models with interactive red-teaming and automated test suites (requires a small amount of coding in a group project). Students will engage real-world legislative proposals and case studies topics including human rights, artwork, the environment, and geopolitics. This course fulfills both the ethics and Writing in the Major WiM requirements, and is designed to prepare Stanford juniors, seniors, and graduate students to participate in AI public policy design at the national and global levels. Prerequisites: PWR1, PWR2, CS106A and CS106B. While this course requires no other prerequisites, it is designed for students who are comfortable engaging in an active learning environment that will include interactive workshops, student debates, and collaborative group projects. Students will be expected to speak frequently in sections and navigate the social dynamics of multi-stakeholder negotiations. Comfort with writing short python programs and working on a Unix/Linux command-line interface will be helpful for the AI model evaluation group project."}, {"id": "CS 139", "slug": "cs139-human-centered-ai", "zh": "人本 AI", "cat": "产品、伦理与设计", "type": "core", "one": "Norvig 的人本 AI：用户心智模型、可信设计、公平与伦理。", "card_desc": "Norvig 的人本 AI：用户心智模型、可信设计、公平与伦理。", "tags": ["人本 AI", "伦理", "产品", "可解释"], "difficulty": 2, "terms": "2027 冬", "units": "3", "search": "CS 139 人本 AI Human-Centered AI Norvig 的人本 AI：用户心智模型、可信设计、公平与伦理。 人本 AI 伦理 产品 可解释 human-centered AI user model trust"}, {"id": "CS 247A", "slug": "cs247a-design-for-artificial-intelligence", "zh": "为人工智能而设计", "cat": "产品、伦理与设计", "type": "core", "one": "为人本 AI 做设计：studio 制，研究、原型、迭代，做出负责任的 AI 体验。", "card_desc": "为人本 AI 做设计：studio 制，研究、原型、迭代，做出负责任的 AI 体验。", "tags": ["设计", "HCI", "人本 AI", "Studio"], "difficulty": 3, "terms": "2026–27 未排课", "units": "3–4", "search": "CS 247A 为人工智能而设计 Design for Artificial Intelligence (SYMSYS 195A) 为人本 AI 做设计：studio 制，研究、原型、迭代，做出负责任的 AI 体验。 设计 HCI 人本 AI Studio design HCI prototype"}, {"id": "CS 256", "slug": "cs-256-algorithmic-fairness", "zh": "算法公平", "cat": "产品、伦理与设计", "type": "ext", "one": "公平性定义、法律框架与带约束的算法设计。", "card_desc": "公平性定义、法律框架与带约束的算法设计。", "tags": ["算法公平"], "difficulty": null, "terms": "2027 春", "units": "3", "search": "CS 256 Algorithmic Fairness 算法公平 公平性定义、法律框架与带约束的算法设计。 Machine learning and data analysis have enjoyed tremendous success in a broad range of domains. These advances hold the promise of great benefits to individuals, organizations and society. Undeniably, algorithms are informing decisions that reach ever more deeply into our lives, from news article recommendations to criminal sentencing decisions to healthcare diagnostics. This progress, however, raises (and is impeded by) a host of concerns regarding the societal impact of computation. A prominent concern is that these algorithms should be fair. Unfortunately, the hope that automated decision-making might be free of social biases is dashed on the data on which the algorithms are trained and the choices in their construction: left to their own devices, algorithms will propagate - even amplify - existing biases of the data, the programmers, and the decisions made in the choice of features to incorporate and measurements of 'fitness' to be applied. Addressing wrongful discrimination by algorithms is not only mandated by law and by ethics but is essential to maintaining the public trust in the current computation-driven revolution.The study of fairness is ancient and multi-disciplinary: philosophers, legal experts, economists, statisticians, social scientists and others have been concerned with fairness for as long as these fields have existed. Nevertheless, the scale of decision making in the age of big-data, the computational complexities of algorithmic decision making, and simple professional responsibility mandate that computer scientists contribute to this research endeavor. This is an intro to this booming area of research. Prerequisites: CS 161. I will be assuming some mathematical maturity, CS 154 is recommended."}, {"id": "CS 281", "slug": "cs281-ethics-of-artificial-intelligence", "zh": "人工智能伦理", "cat": "产品、伦理与设计", "type": "core", "one": "AI 伦理的技术侧：公平、可解释、隐私，以及这些方法的形式化极限。", "card_desc": "AI 伦理的技术侧：公平、可解释、隐私，以及这些方法的形式化极限。", "tags": ["伦理", "公平", "可解释", "隐私"], "difficulty": 3, "terms": "2026–27 未排课", "units": "3–4", "search": "CS 281 人工智能伦理 Ethics of Artificial Intelligence AI 伦理的技术侧：公平、可解释、隐私，以及这些方法的形式化极限。 伦理 公平 可解释 隐私 ethics fairness interpretability privacy"}, {"id": "CS 293", "slug": "cs-293-empowering-educators-via-language-technology-educ-473", "zh": "语言技术 × 教育", "cat": "产品、伦理与设计", "type": "ext", "one": "用 NLP 分析教学实践，服务教师与课堂。", "card_desc": "用 NLP 分析教学实践，服务教师与课堂。", "tags": ["语言技术 × 教育"], "difficulty": null, "terms": "2026–27 未排课", "units": "2–4", "search": "CS 293 Empowering Educators via Language Technology (EDUC 473) 语言技术 × 教育 用 NLP 分析教学实践，服务教师与课堂。 This course explores the use of natural language processing (NLP) to support educators, by discovering, measuring, and analyzing high-leverage teaching practices. Topics include computational social science methods, ethics, bias and fairness, automated scoring, causal analyses, large language models, among others. Engaging with relevant papers, students will work towards a final project using NLP methods and a critical social scientific lens. Projects are pitched to a jury of educators at the end of the course."}, {"id": "CS 323", "slug": "cs-323-the-ai-awakening-implications-for-the-economy-and-society", "zh": "AI 经济与社会", "cat": "产品、伦理与设计", "type": "ext", "one": "AI 对劳动、创业与政策的影响，含产业 guest lecture。", "card_desc": "AI 对劳动、创业与政策的影响，含产业 guest lecture。", "tags": ["AI 经济与社会"], "difficulty": null, "terms": "2027 春", "units": "3–4", "search": "CS 323 The AI Awakening: Implications for the Economy and Society AI 经济与社会 AI 对劳动、创业与政策的影响，含产业 guest lecture。 This course examines how advances in AI are transforming the economy and reshaping the frontier of entrepreneurship. In Spring 2026, the course will emphasize venture creation: students will explore how large language models and other AI tools enable small teams to build products and companies with unprecedented speed and scale. Each week features guest speakers who are leaders in AI, business, economics, and industry, alongside discussion of cutting-edge research and its practical implications. Working in interdisciplinary teams, students will develop, prototype, and refine an AI-enabled product or startup concept, culminating in a final presentation of a working prototype and venture strategy. Designed primarily for graduate students in economics, business, computer science, and related fields. Admission is by application only. To learn more and apply, please visit https://digitaleconomy.stanford.edu/about/education/the-ai-awakening-implications-for-the-economy-and-society/; applications close at 5pm PT on March 16, 2026, with priority given to those received by March 9."}, {"id": "CS 384", "slug": "cs-384-seminar-on-ethical-and-social-issues-in-natural-language-processing-linguist-287", "zh": "NLP 伦理 seminar", "cat": "产品、伦理与设计", "type": "ext", "one": "NLP 中的偏见、隐私、毒性、操纵与权力。", "card_desc": "NLP 中的偏见、隐私、毒性、操纵与权力。", "tags": ["NLP 伦理 seminar"], "difficulty": null, "terms": "2026–27 未排课", "units": "3–4", "search": "CS 384 Seminar on Ethical and Social Issues in Natural Language Processing (LINGUIST 287) NLP 伦理 seminar NLP 中的偏见、隐私、毒性、操纵与权力。 Seminar covering issues in natural language processing related to ethical and social issues and the overall impact of these algorithms on people and society. Topics include: bias in data and models, privacy and computational profiling, measuring civility and toxicity online, computational propaganda, manipulation and framing, fairness/equity, power, recommendations and filter bubbles, applications to social good, and philosophical foundations of ethical investigation. Prerequisites: CS 224N and 224U."}, {"id": "EDUC 246I", "slug": "educ-246i-ai-and-education-foundations-opportunities-challenges-and-considerations", "zh": "AI 与教育", "cat": "产品、伦理与设计", "type": "ext", "one": "面向教师的 AI/edTech 机会、挑战与伦理。", "card_desc": "面向教师的 AI/edTech 机会、挑战与伦理。", "tags": ["AI 与教育"], "difficulty": null, "terms": "2026 秋", "units": "1", "search": "EDUC 246I AI and Education: Foundations, Opportunities, Challenges, and Considerations AI 与教育 面向教师的 AI/edTech 机会、挑战与伦理。 Generative Artificial Intelligence, and edTech more broadly, are areas of growing interest and influence on the work of P-12 teachers and educational leaders. Our hopes for this mini-course are to begin exploring together some of the opportunities, puzzles, possibilities, and concerns around the AI/edTech space to better inform our work individually and collectively. As classroom teachers you will be charged to make informed decisions to support the growth and learning of your students, the elevate the goals and flourish of your students, and to support the broader aspirations you have about the impact of education on society. Deepening your knowledge, skills, and understanding of the complexities in this emerging and influential field will inform your judgements, perspectives, decisions, and actions involving AI and other educational technologies. For STEP Program students only."}, {"id": "EE 205", "slug": "ee-205-product-management-for-engineers-in-the-ai-age", "zh": "AI 时代产品管理", "cat": "产品、伦理与设计", "type": "ext", "one": "从用户问题到 GTM，与企业合作做真实 AI 产品。", "card_desc": "从用户问题到 GTM，与企业合作做真实 AI 产品。", "tags": ["AI 时代产品管理"], "difficulty": null, "terms": "2027 冬", "units": "3", "search": "EE 205 Product Management for Engineers in the AI Age AI 时代产品管理 从用户问题到 GTM，与企业合作做真实 AI 产品。 Introduction to the core principles of Product Management in the age of AI. Open by application to graduate engineering students (and coterms). EE 205 teaches students to find the right problem to solve for customers, build a solution, and bring it to market.nnAI makes building easier, allowing engineers to accomplish more in the time available. The starting point remains critical: interview people, spend time with customers, and understand the problems they actually face. Students use AI to rapidly prototype, iterate, and build an end product. In the second half of the course, the focus shifts to sales and go-to-market, with the goal of solving real problems for customers.nSelected readings and cases introduce strategic tools that broaden students' understanding of product management and strengthen their problem analysis skills. Topics include the customer's &quot;job to be done,&quot; customer centricity, and the competitive forces shaping a market. Case discussions develop students' ability to apply these tools to decisions about what to build and how to bring it to customers.nThirty graduate engineering students work in five teams of six, each with a corporate partner. Corporate partners for 2027 are BMW, Omron Robotics, AGI Inc (on device AI), AI-Fabrik (neo-cloud data center) and Ambarella (semiconductor chip). Students choice rank their corporate partners.nnCommunication, public speaking, and GTM are central. As AI makes building easier, understanding people, empathizing, and establishing trust become even more important. One of Stanford's highest rated classes.nnApplication only - apply here by Nov 20th: https://forms.gle/LZFaXjjhAdmUrG8cA"}, {"id": "MS&E 203", "slug": "mse203-building-and-evaluating-ai-products", "zh": "构建与评估 AI 产品", "cat": "产品、伦理与设计", "type": "core", "one": "从 0 到 1 做 AI 产品和 agent：AI fit、延迟/质量/成本、eval、Demo Day。", "card_desc": "从 0 到 1 做 AI 产品和 agent：AI fit、延迟/质量/成本、eval、Demo Day。", "tags": ["产品", "Agent", "Eval", "创业"], "difficulty": 3, "terms": "2026 秋", "units": "3", "search": "MS&E 203 构建与评估 AI 产品 Building and Evaluating AI Products 从 0 到 1 做 AI 产品和 agent：AI fit、延迟/质量/成本、eval、Demo Day。 产品 Agent Eval 创业 Why AI Products Are Different Product Discovery in the Age of AI Evals Fundamentals Improving the Product Multi-Turn Evaluation and Simulation User Research Beyond the Metrics When AI Products Fail (Case Study) Responsible AI Voice and Multimodal (Case Study) Demo Day AI product eval red team demo day"}, {"id": "SYMSYS 122", "slug": "symsys-122-the-social-economic-impact-of-artificial-intelligence-cs-22a-intlpol-200", "zh": "AI 社会经济影响", "cat": "产品、伦理与设计", "type": "ext", "one": "非技术视角看 AI 对劳动、医疗、教育与地缘政治的影响。", "card_desc": "非技术视角看 AI 对劳动、医疗、教育与地缘政治的影响。", "tags": ["AI 社会经济影响"], "difficulty": null, "terms": "2027 冬", "units": "1", "search": "SYMSYS 122 The Social & Economic Impact of Artificial Intelligence (CS 22A, INTLPOL 200) AI 社会经济影响 非技术视角看 AI 对劳动、医疗、教育与地缘政治的影响。 Recent advances in Generative AI are rapidly transforming how we live and work. This lecture course offers a non-technical exploration of its foundational principles, inherent strengths and limitations, and a comprehensive overview of its profound impact on our society and economy. We will delve into critical questions: How will AI reshape labor markets and jobs? What roles will it play in medical research, healthcare, education, entertainment, engineering, transportation, and the legal system? How will it be used - or misused - in democratic societies and autocratic regimes? Will it alter the geopolitical balance of power and the nature of warfare? How can we align these powerful systems with human values? Can machines genuinely create, or possess consciousness? Does the prospect of superintelligence mean the human race is doomed? Will the benefits of this technological revolution be broadly distributed, or accrue to a lucky few? Are we currently experiencing an 'AI bubble'? This course also demystifies essential jargon, such as 'transformers', 'prompt engineering', 'chain of thought', 'hallucination', 'jailbreaking', 'context rot', 'deepfakes', 'stochastic parrots', and 'algorithmic bias'. By equipping students with historical grounding, intellectual tools, ethical frameworks, and psychological perspectives, this course prepares them to thoughtfully navigate the complexities of the AI revolution. (Note: This course is pre-approved for credit at Stanford Law School (SLS) and the Graduate School of Business (GSB). GSB students must enroll in either SYMSYS 122 or INTLPOL 200 for GSB credit. No programming or prior technical knowledge is required.)"}, {"id": "CME 216", "slug": "cme-216-machine-learning-for-computational-engineering-me-343", "zh": "ML × 计算工程", "cat": "统计与优化", "type": "ext", "one": "核方法、深度学习、自动微分与物理约束 ML。", "card_desc": "核方法、深度学习、自动微分与物理约束 ML。", "tags": ["ML × 计算工程"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CME 216 Machine Learning for Computational Engineering. (ME 343) ML × 计算工程 核方法、深度学习、自动微分与物理约束 ML。 Linear and kernel support vector machines, deep learning, deep neural networks, generative adversarial networks, physics-based machine learning, forward and reverse mode automatic differentiation, optimization algorithms for machine learning, TensorFlow, PyTorch."}, {"id": "CS 225", "slug": "cs-225-machine-learning-for-discrete-optimization-mse-236", "zh": "ML × 离散优化", "cat": "统计与优化", "type": "ext", "one": "用 GNN、RL、LLM 学习启发式，改进组合优化求解。", "card_desc": "用 GNN、RL、LLM 学习启发式，改进组合优化求解。", "tags": ["ML × 离散优化"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CS 225 Machine Learning for Discrete Optimization (MS&E 236) ML × 离散优化 用 GNN、RL、LLM 学习启发式，改进组合优化求解。 Machine learning has become a powerful tool for discrete optimization. This is because, in practice, we often have ample data about the application domain?data that can be used to optimize algorithmic performance, ranging from runtime to solution quality. This course covers how machine learning can be used within the discrete optimization pipeline from many perspectives, including how to design novel combinatorial algorithms with machine-learned modules and configure existing algorithms? parameters to optimize performance. Topics will include both applied machinery (such as graph neural networks, reinforcement learning, transformers, and LLMs) as well as theoretical tools for providing provable guarantees."}, {"id": "CS 238", "slug": "cs-238-decision-making-under-uncertainty-aa-228", "zh": "不确定性下的决策", "cat": "统计与优化", "type": "ext", "one": "POMDP、动态规划与 RL 在航空航天决策中的应用。", "card_desc": "POMDP、动态规划与 RL 在航空航天决策中的应用。", "tags": ["不确定性下的决策"], "difficulty": null, "terms": "2026 秋", "units": "3–4", "search": "CS 238 Decision Making under Uncertainty (AA 228) 不确定性下的决策 POMDP、动态规划与 RL 在航空航天决策中的应用。 This course is designed to increase awareness and appreciation for why uncertainty matters, particularly for aerospace applications. Introduces decision making under uncertainty from a computational perspective and provides an overview of the necessary tools for building autonomous and decision-support systems. Following an introduction to probabilistic models and decision theory, the course will cover computational methods for solving decision problems with stochastic dynamics, model uncertainty, and imperfect state information. Topics include: Bayesian networks, influence diagrams, dynamic programming, reinforcement learning, and partially observable Markov decision processes. Applications cover: air traffic control, aviation surveillance systems, autonomous vehicles, and robotic planetary exploration. Prerequisites: basic probability and fluency in a high-level programming language."}, {"id": "CS 239", "slug": "cs-239-advanced-topics-in-sequential-decision-making-aa-229", "zh": "序列决策进阶", "cat": "统计与优化", "type": "ext", "one": "多智能体、部分可观测与近似动态规划的研究专题。", "card_desc": "多智能体、部分可观测与近似动态规划的研究专题。", "tags": ["序列决策进阶"], "difficulty": null, "terms": "2027 冬", "units": "3–4", "search": "CS 239 Advanced Topics in Sequential Decision Making (AA 229) 序列决策进阶 多智能体、部分可观测与近似动态规划的研究专题。 Survey of recent research advances in intelligent decision making for dynamic environments from a computational perspective. Efficient algorithms for single and multiagent planning in situations where a model of the environment may or may not be known. Partially observable Markov decision processes, approximate dynamic programming, and reinforcement learning. New approaches for overcoming challenges in generalization from experience, exploration of the environment, and model representation so that these methods can scale to real problems in a variety of domains including aerospace, air traffic control, and robotics. Students are expected to produce an original research paper on a relevant topic. Prerequisites: AA 228/CS 238 or CS 221."}, {"id": "CS 321M", "slug": "cs-321m-ai-measurement-science", "zh": "AI 测量科学", "cat": "统计与优化", "type": "ext", "one": "基准、心理测量与效度理论，系统评估 AI 能力。", "card_desc": "基准、心理测量与效度理论，系统评估 AI 能力。", "tags": ["AI 测量科学"], "difficulty": null, "terms": "2027 春", "units": "3", "search": "CS 321M AI Measurement Science AI 测量科学 基准、心理测量与效度理论，系统评估 AI 能力。 Artificial Intelligence (AI) measurement science provides frameworks and methodologies for evaluating, benchmarking, and understanding AI systems. As AI systems become increasingly powerful and deploy into high-stakes domains, the need for rigorous measurement approaches has grown in importance. Current measurement approaches are often ad hoc, lacking theoretical grounding, and failing to connect to real-world use cases. This has led to a measurement crisis characterized by benchmark saturation, inconsistent evaluation methodologies, and difficulty in making valid claims about AI capabilities. This course will cover the foundations of AI measurement science from first principles and outline connections to the growing literature on the topic. This includes: validity theory as applied to AI evaluation, focusing on content, criterion, construct, external, and consequential validity; psychometric models for AI measurement, including item response theory and latent variable models; scaling laws and intervention effects, predicting the impacts of data, computing, and architecture choices; synthetic data generation for evaluation and its implications; governance and policy considerations around AI measurement. This is a graduate-level course. By the end of the course, students should be able to understand, implement, and critique state-of-the-art AI measurement approaches and be ready to conduct research on these topics."}, {"id": "CS 328", "slug": "cs-328-foundations-of-causal-machine-learning", "zh": "因果机器学习", "cat": "统计与优化", "type": "ext", "one": "半参数效率、DML、异质处理效应与 off-policy 评估。", "card_desc": "半参数效率、DML、异质处理效应与 off-policy 评估。", "tags": ["因果机器学习"], "difficulty": null, "terms": "2027 冬", "units": "3", "search": "CS 328 Foundations of Causal Machine Learning 因果机器学习 半参数效率、DML、异质处理效应与 off-policy 评估。 Theoretical foundations of modern techniques at the intersection of causal inference and machine learning. Topics may include: semi-parametric inference and semi-parametric efficiency, modern statistical learning theory, Neyman orthogonality and double/debiased machine learning, theoretical foundations of high-dimensional linear regression, theoretical foundations of non-linear regression models, such as random forests and neural networks, adaptive non-parametric estimation of conditional moment models, estimation and inference on heterogeneous treatment effects, causal inference and reinforcement learning, off-policy evaluation, adaptive experimentation and inference."}, {"id": "CS 331X", "slug": "cs-331x-ai-for-algorithmic-reasoning-and-optimization-mse-331", "zh": "AI × 算法优化", "cat": "统计与优化", "type": "ext", "one": "用 GNN、扩散模型与 LLM 参与算法设计与调参。", "card_desc": "用 GNN、扩散模型与 LLM 参与算法设计与调参。", "tags": ["AI × 算法优化"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "CS 331X AI for Algorithmic Reasoning and Optimization (MS&E 331) AI × 算法优化 用 GNN、扩散模型与 LLM 参与算法设计与调参。 Artificial intelligence is expanding the frontier of algorithm design, enabling new ways to reason about and solve complex optimization problems. This course explores how AI methods - ranging from graph neural networks and diffusion models to large language models - can be integrated into the algorithm design pipeline. We will study how to use machine learning to design new algorithms, enhance classical algorithms with data-driven components, and optimize algorithm performance in specific application domains. Topics will span both practical approaches, such as differentiable optimization and generative AI for combinatorial problems, to theoretical perspectives, including approximation guarantees and the limits of learned algorithms."}, {"id": "MS&E 226", "slug": "mse-226-fundamentals-of-data-science-prediction-inference-causality", "zh": "数据科学基础", "cat": "统计与优化", "type": "ext", "one": "预测、推断与因果三种视角的统一框架。", "card_desc": "预测、推断与因果三种视角的统一框架。", "tags": ["数据科学基础"], "difficulty": null, "terms": "2026 秋", "units": "3", "search": "MS&E 226 Fundamentals of Data Science: Prediction, Inference, Causality 数据科学基础 预测、推断与因果三种视角的统一框架。 This course provides an introduction to applied data analysis, with an emphasis on providing a conceptual framework for thinking about uncertainty from machine learning, statistical, and causal perspectives. The class involves developing an interconnected understanding across these ways of thinking. Class lectures will be supplemented by data-driven problem sets and a project. Prerequisites: multivariable calculus; probability."}, {"id": "MS&E 228", "slug": "mse-228-applied-causal-inference-with-machine-learning-and-ai-cs-288", "zh": "因果推断 × ML", "cat": "统计与优化", "type": "ext", "one": "高维数据下的因果估计与政策评估。", "card_desc": "高维数据下的因果估计与政策评估。", "tags": ["因果推断 × ML"], "difficulty": null, "terms": "2027 冬", "units": "3", "search": "MS&E 228 Applied Causal Inference with Machine Learning and AI (CS 288) 因果推断 × ML 高维数据下的因果估计与政策评估。 Fundamentals of modern applied causal inference. The course introduces the basic principles of causal inference and machine learning and shows how the two combine in practice to deliver causal insights and policy implications in real-world datasets, allowing for high-dimensionality and flexible estimation. Lectures provide the foundations of these new methodologies and proofs of their properties, and course assignments involve real-world data (from the social sciences and tech industry) as well as synthetic data analysis based on these methodologies. Prerequisites include mathematical maturity in probability, statistics, optimization, linear algebra, and calculus. Recommended: MS&amp;E 226 or equivalent."}, {"id": "MS&E 235A", "slug": "mse-235a-markov-decision-processes-ee-283", "zh": "马尔可夫决策过程", "cat": "统计与优化", "type": "ext", "one": "MDP、值迭代、策略迭代与 bandit 基础。", "card_desc": "MDP、值迭代、策略迭代与 bandit 基础。", "tags": ["马尔可夫决策过程"], "difficulty": null, "terms": "2026 秋", "units": "3", "search": "MS&E 235A Markov Decision Processes (EE 283) 马尔可夫决策过程 MDP、值迭代、策略迭代与 bandit 基础。 Formulation and solution of sequential decision problems under uncertainty as a foundation for artificial intelligence, operations research, and economics. Finite-horizon, discounted, and average reward objectives. Optimization via value iteration, policy iteration, linear programming, and reinforcement learning algorithms. Semi-Markov decision processes. Multi-armed bandits and the Gittin's index theorem. Use of partial state information. Homework assignments involve a combination of analytic and computational exercises."}, {"id": "MS&E 235B", "slug": "mse-235b-reinforcement-learning-behaviors-and-applications-ee-383", "zh": "强化学习", "cat": "统计与优化", "type": "ext", "one": "面向应用的 RL 行为设计与可扩展算法。", "card_desc": "面向应用的 RL 行为设计与可扩展算法。", "tags": ["强化学习"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "MS&E 235B Reinforcement Learning: Behaviors and Applications (EE 383) 强化学习 面向应用的 RL 行为设计与可扩展算法。 The subject of reinforcement learning addresses the design of agents that improve decisions over time while operating within complex environments. This course covers desired agent behaviors and principled scalable approaches to realizing such behavior. Homework assignments primarily involve programming exercises carried out in Colab."}, {"id": "MS&E 318", "slug": "mse318-safe-and-constrained-ai", "zh": "安全与受约束的 AI", "cat": "统计与优化", "type": "core", "one": "安全约束 AI：约束优化、safe RL、投影网络、LLM alignment。", "card_desc": "安全约束 AI：约束优化、safe RL、投影网络、LLM alignment。", "tags": ["安全", "约束优化", "RL", "对齐"], "difficulty": 5, "terms": "2026–27 未排课", "units": "3", "search": "MS&E 318 安全与受约束的 AI Safe and Constrained AI 安全约束 AI：约束优化、safe RL、投影网络、LLM alignment。 安全 约束优化 RL 对齐 safe RL constrained alignment"}, {"id": "MS&E 319", "slug": "mse319-efficient-generative-models", "zh": "高效生成模型", "cat": "统计与优化", "type": "core", "one": "高效生成模型：在推理深度、算力、延迟、内存、数据之间做权衡，重点是 LLM。", "card_desc": "高效生成模型：在推理深度、算力、延迟、内存、数据之间做权衡，重点是 LLM。", "tags": ["生成模型", "效率", "LLM", "系统"], "difficulty": 4, "terms": "2026 秋", "units": "3", "search": "MS&E 319 高效生成模型 Efficient Generative Models 高效生成模型：在推理深度、算力、延迟、内存、数据之间做权衡，重点是 LLM。 生成模型 效率 LLM 系统 Overview of the Course and LLMs A Review of LLM Architecture and Training Making Compute Go Further Mixtures of Experts Efficient Attention: KV Caching, Sparse Attention, Compression Efficient Attention: Compact KV-Cache Representations Positional Embeddings and Recurrent Memory Language Model Quantization I: Quantizing Vectors Language Model Quantization II: Quantizing Matrices Speculative Decoding and Efficient Inference Post-training I: SFT, LoRA, RLHF Post-training II: RLHF and DPO Distillation and Recursive Self-Improvement Risks and Vulnerabilities of Generative AI (I) Risks and Vulnerabilities of Generative AI (II) Where Do We Go from Here? MoE KV cache quantization speculative decoding RLHF"}, {"id": "MS&E 328", "slug": "mse-328-foundations-of-causal-machine-learning", "zh": "因果 ML 基础", "cat": "统计与优化", "type": "ext", "one": "与 CS 328 交叉的因果推断理论。", "card_desc": "与 CS 328 交叉的因果推断理论。", "tags": ["因果 ML 基础"], "difficulty": null, "terms": "2027 冬", "units": "3", "search": "MS&E 328 Foundations of Causal Machine Learning 因果 ML 基础 与 CS 328 交叉的因果推断理论。 Theoretical foundations of modern techniques at the intersection of causal inference and machine learning. Topics may include: semi-parametric inference and semi-parametric efficiency, modern statistical learning theory, Neyman orthogonality and double/debiased machine learning, theoretical foundations of high-dimensional linear regression, theoretical foundations of non-linear regression models, such as random forests and neural networks, adaptive non-parametric estimation of conditional moment models, estimation and inference on heterogeneous treatment effects, causal inference and reinforcement learning, off-policy evaluation, adaptive experimentation and inference."}, {"id": "MS&E 330", "slug": "mse-330-reliability-and-validity-in-artificial-intelligence-stats-357", "zh": "AI 可靠性", "cat": "统计与优化", "type": "ext", "one": "与 STATS 357 交叉的 AI 评估与效度。", "card_desc": "与 STATS 357 交叉的 AI 评估与效度。", "tags": ["AI 可靠性"], "difficulty": null, "terms": "2027 冬", "units": "3", "search": "MS&E 330 Reliability and Validity in Artificial Intelligence (STATS 357) AI 可靠性 与 STATS 357 交叉的 AI 评估与效度。 This course examines the principles and methods required to make artificial intelligence (AI) systems reliable and scientifically sound. Topics include evaluation and benchmarking, notions of validity, distribution shift, causality, predictive inference, AI-assisted statistical inference, data attribution, and beyond. Problem sets will involve both mathematical components and coding projects to see the practical effects of the methods we develop."}, {"id": "MS&E 346", "slug": "mse-346-foundations-of-reinforcement-learning-with-applications-in-finance-cme-241", "zh": "RL × 金融", "cat": "统计与优化", "type": "ext", "one": "把交易、对冲与组合管理建模成 RL 问题。", "card_desc": "把交易、对冲与组合管理建模成 RL 问题。", "tags": ["RL × 金融"], "difficulty": null, "terms": "2027 冬", "units": "3", "search": "MS&E 346 Foundations of Reinforcement Learning with Applications in Finance (CME 241) RL × 金融 把交易、对冲与组合管理建模成 RL 问题。 This course is taught in 3 modules - (1) Markov Processes and Planning Algorithms, including Approximate Dynamic Programming (3 weeks), (2) Financial Trading problems cast as Stochastic Control, from the fields of Portfolio Management, Derivatives Pricing/Hedging, Order-Book Trading (2 weeks), and (3) Reinforcement Learning Algorithms, including Monte-Carlo, Temporal-Difference, Batch RL, Policy Gradient (4 weeks). The final week will cover practical aspects of RL in the industry, including an industry guest speaker. The course emphasizes the theory of RL, modeling the practical nuances of these finance problems, and strengthening the understanding through plenty of programming exercises. No pre-requisite coursework expected, but a foundation in undergraduate Probability, basic familiarity with Finance, and Python programming skills are required."}, {"id": "MS&E 446", "slug": "mse-446-artificial-intelligence-in-financial-technology", "zh": "AI × 金融科技", "cat": "统计与优化", "type": "ext", "one": "金融科技中的 AI 应用与小组项目。", "card_desc": "金融科技中的 AI 应用与小组项目。", "tags": ["AI × 金融科技"], "difficulty": null, "terms": "2026–27 未排课", "units": "3", "search": "MS&E 446 Artificial Intelligence in Financial Technology AI × 金融科技 金融科技中的 AI 应用与小组项目。 This course surveys the current Financial Technology landscape through the lens of Artificial Intelligence applications. Students work in groups of four to develop an original financial technology project, research paper, or product prototype within a chosen area. They present final project posters to the class and post them online. Top posters are selected for presentation at the AI in Fintech Forum. Advanced undergraduates, graduate students, and students from other schools are welcome to enroll. Prerequisites include strong programming skills, knowledge of the design process, and applied statistics; no formal finance experience is required. Enrollment is capped at 3 units, and the course is letter graded."}, {"id": "STATS 202", "slug": "stats202-statistical-learning-and-data-science", "zh": "统计学习与数据科学", "cat": "统计与优化", "type": "core", "one": "统计学习入门：回归/分类、正则、树/集成、SVM、神经网络、聚类。", "card_desc": "统计学习入门：回归/分类、正则、树/集成、SVM、神经网络、聚类。", "tags": ["统计学习", "数据科学", "回归"], "difficulty": 3, "terms": "2027 冬 / 2027 春", "units": "3", "search": "STATS 202 统计学习与数据科学 Statistical Learning and Data Science 统计学习入门：回归/分类、正则、树/集成、SVM、神经网络、聚类。 统计学习 数据科学 回归 regression classification regularization"}, {"id": "STATS 315A", "slug": "stats315a-modern-applied-statistics-learning", "zh": "现代应用统计：学习", "cat": "统计与优化", "type": "core", "one": "现代应用统计学习：预测方法、模型评估、优化、生成模型。", "card_desc": "现代应用统计学习：预测方法、模型评估、优化、生成模型。", "tags": ["统计学习", "生成模型", "评估"], "difficulty": 4, "terms": "2027 冬", "units": "3", "search": "STATS 315A 现代应用统计：学习 Modern Applied Statistics: Learning 现代应用统计学习：预测方法、模型评估、优化、生成模型。 统计学习 生成模型 评估 statistical learning generative model evaluation"}, {"id": "STATS 357", "slug": "stats-357-reliability-and-validity-in-artificial-intelligence-mse-330", "zh": "AI 可靠性", "cat": "统计与优化", "type": "ext", "one": "评估、效度、分布偏移与 AI 辅助统计推断。", "card_desc": "评估、效度、分布偏移与 AI 辅助统计推断。", "tags": ["AI 可靠性"], "difficulty": null, "terms": "2027 冬", "units": "3", "search": "STATS 357 Reliability and Validity in Artificial Intelligence (MS&E 330) AI 可靠性 评估、效度、分布偏移与 AI 辅助统计推断。 This course examines the principles and methods required to make artificial intelligence (AI) systems reliable and scientifically sound. Topics include evaluation and benchmarking, notions of validity, distribution shift, causality, predictive inference, AI-assisted statistical inference, data attribution, and beyond. Problem sets will involve both mathematical components and coding projects to see the practical effects of the methods we develop."}];
